    object SessionNotFound : OnboardErrorReason("session_not_found")
    object SessionExpired : OnboardErrorReason("session_expired")
    object SessionInvalidated : OnboardErrorReason("session_invalidated")
    object HubMismatch : OnboardErrorReason("hub_mismatch")
    object NotPermitted : OnboardErrorReason("not_permitted")
    object Declined : OnboardErrorReason("declined")
    object Cancelled : OnboardErrorReason("cancelled")
    object PlatformNotSupported : OnboardErrorReason("platform_not_supported")
    object AreasNotAllowed : OnboardErrorReason("areas_not_allowed")
    object TooManyAttempts : OnboardErrorReason("too_many_attempts")
    object KindNotAllowed : OnboardErrorReason("kind_not_allowed")
    object ProfileNotAllowed : OnboardErrorReason("profile_not_allowed")
