/**
 * Who opened a device early or answered its request: device = a recipient device (set up the
 * device, may set up its kind, or a family manager for a babysitter); admin = the admin UI; hub =
 * the hub (expiry). Names are display names at that time; never HA user ids, tokens or IP
 * addresses.
 */
@Serializable
data class AccessRequestActor(
    @SerialName("kind") val kind: AccessRequestActorKind,
    @SerialName("client_id") val clientId: String?,
    /**
     * Owner label (first name) of the device, else its name; admin display name for admin.
     */
    @SerialName("name") val name: String,
    @SerialName("owner_label") val ownerLabel: String? = null,
    @SerialName("via") val via: FamilyRoute? = null,
) : ContractValue {
    override fun validate(path: String): List<ContractViolation> {
        val v_ = mutableListOf<ContractViolation>()
        ContractCheck.nested(v_, path + "/kind", kind)
        ContractCheck.string(v_, path + "/client_id", clientId, rule = ContractCheck.StringRule(pattern = ContractPatterns.P1))
        ContractCheck.string(v_, path + "/name", name, rule = ContractCheck.StringRule(maxLength = 100))
        ContractCheck.string(v_, path + "/owner_label", ownerLabel, rule = ContractCheck.StringRule(maxLength = 50))
        ContractCheck.nested(v_, path + "/via", via)
        return v_
    }
}

/**
 * A running early access of a device – a Yes to its request (or the admin) opened it before its
 * access hours allow. Only the schedule part: the access switch still applies. The hub deletes it
 * at until; until is never in the past while it is shown.
 */
@Serializable
data class AccessEarly(
    /**
     * End of the early access (UTC).
     */
    @SerialName("until") val until: String,
    @SerialName("by") val by: AccessRequestActor,
    @SerialName("request_id") val requestId: String?,
    @SerialName("duration") val duration: AccessRequestDuration? = null,
    /**
     * When it was granted.
     */
    @SerialName("at") val at: String,
) : ContractValue {
    override fun validate(path: String): List<ContractViolation> {
        val v_ = mutableListOf<ContractViolation>()
        ContractCheck.nested(v_, path + "/by", by)
        ContractCheck.string(v_, path + "/request_id", requestId, rule = ContractCheck.StringRule(pattern = ContractPatterns.P1))
        ContractCheck.nested(v_, path + "/duration", duration)
        return v_
    }
}

/**
 * Window of the rule access_hours in the hub time zone (Home Assistant's time_zone): the device
 * has access from start to end on the listed days. Same form as a bedtime window: end <= start
 * crosses midnight and belongs to the start day (fri 18:00-01:00 ends Saturday 01:00); start ==
 * end = 24 hours from start. Windows that touch or overlap are one continuous access.
 */
@Serializable
data class AccessWindow(
    @SerialName("days") val days: List<KidsWeekday>,
    @SerialName("start") val start: String,
    @SerialName("end") val end: String,
) : ContractValue {
    override fun validate(path: String): List<ContractViolation> {
        val v_ = mutableListOf<ContractViolation>()
        ContractCheck.items(v_, path + "/days", days, minItems = 1, maxItems = 7, unique = true)
        ContractCheck.nested(v_, path + "/days", days)
        ContractCheck.string(v_, path + "/start", start, rule = ContractCheck.StringRule(pattern = ContractPatterns.P2))
        ContractCheck.string(v_, path + "/end", end, rule = ContractCheck.StringRule(pattern = ContractPatterns.P2))
        return v_
    }
}

/**
 * Value of the profile rule access_hours (“Access hours”, docs/access.md): enabled = the device
 * has access only inside the windows; outside it stays paired but sees nothing (no areas, no
 * states, no control) and only shows when access opens again. enabled false = no time limit (the
 * access switch still applies). enabled with no window = no access at all.
 */
@Serializable
data class AccessHours(
    @SerialName("enabled") val enabled: StrictBoolean,
    @SerialName("windows") val windows: List<AccessWindow>,
) : ContractValue {
    override fun validate(path: String): List<ContractViolation> {
        val v_ = mutableListOf<ContractViolation>()
        ContractCheck.items(v_, path + "/windows", windows, maxItems = 14)
        ContractCheck.nested(v_, path + "/windows", windows)
        return v_
    }
}

/**
 * Access of a device right now (docs/access.md): open = access hours (when enabled) allow now AND
 * the access switch (when the device has one) is on. Computed by the hub in Home Assistant's time
 * zone; reference tools/access_ref.py, vectors fixtures/profiles/access-hours. The app shows only
 * “Access again from …” while open is false. early = a running early access (a Yes to the device's
 * request): open while the switch allows it, until follows the early access and the windows that
 * continue it.
 */
@Serializable
data class AccessNow(
    @SerialName("open") val open: StrictBoolean,
    /**
     * Only while closed; null while open.
     */
    @SerialName("reason") val reason: AccessClosedReason?,
    /**
     * Open: end of the running access window (windows that touch are followed to their common end);
     * null = open without a time limit (no access hours). Closed: null.
     */
    @SerialName("until") val until: String?,
    /**
     * Closed by the schedule with the switch on: start of the next window (within 8 days). null while
     * open, while the switch is off (nobody knows when it is switched on again) and when no window
     * comes.
     */
    @SerialName("opens_at") val opensAt: String?,
    /**
     * The effective rule access_hours is enabled.
     */
    @SerialName("schedule") val schedule: StrictBoolean,
    /**
     * State of the device's access switch; null = the device has no switch (no access hours and not of
     * kind guest, house_sitter or babysitter).
     */
    @SerialName("switch") val switch: StrictBoolean?,
    /**
     * Running early access (until in the future), null or missing = none. While it runs, open is true
     * unless the switch is off; until is the end of the early access or of the windows that follow it
     * directly.
     */
    @SerialName("early") val early: AccessEarly? = null,
) : ContractValue {
    override fun validate(path: String): List<ContractViolation> {
        val v_ = mutableListOf<ContractViolation>()
        ContractCheck.nested(v_, path + "/reason", reason)
        ContractCheck.nested(v_, path + "/early", early)
        return v_
    }
}

