        ContractCheck.string(v_, path + "/entity_id", entityId, rule = ContractCheck.StringRule(pattern = ContractPatterns.P8, maxLength = 255))
        val present_ = mutableSetOf<String>()
        present_.add("source")
        if (attribute != null) present_.add("attribute")
        if (entityId != null) present_.add("entity_id")
        val c0_ = source.value in listOf("attribute")
        val c1_ = source.value in listOf("entity")
        ContractCheck.obj(v_, path, present_, conditionals = listOf(ContractCheck.Conditional(c0_, listOf("attribute"), listOf(), listOf(), listOf("attribute")), ContractCheck.Conditional(c1_, listOf("entity_id"), listOf(), listOf(), listOf("entity_id"))))
        return v_
    }
}

