/**
 * TXT keys of the hub's mDNS announcement. All values are strings. Clients must ignore unknown
 * keys.
 * Schema: `schemas/bonjour/txt-record.json`.
 */
@Serializable
data class BonjourTxtRecord(
    @SerialName("ws_path") val wsPath: String,
    @SerialName("api_path") val apiPath: String,
    /**
     * Only when an App URL is configured.
     */
    @SerialName("app_url") val appUrl: String? = null,
    /**
     * Only when a TLS certificate exists (also when tls_enabled is false).
     */
    @SerialName("tls") val tls: String? = null,
    /**
     * String, e.g. "8100".
     */
    @SerialName("tls_port") val tlsPort: String? = null,
    @SerialName("fp") val fp: String? = null,
    /**
     * Hub version (e.g. 2026.12.0). Informational; compatibility is decided by pv.
     */
    @SerialName("version") val version: String,
    /**
     * Stable hub instance id; two hubs in one LAN are distinguishable.
     */
    @SerialName("iid") val iid: String,
    /**
     * protocol_version of the hub as a decimal string.
     */
    @SerialName("pv") val pv: String,
    /**
     * min_protocol_version of the hub as a decimal string. An app below it shows 'update the app'
     * before pairing.
     */
    @SerialName("pv_min") val pvMin: String,
) : ContractValue {
    override fun validate(path: String): List<ContractViolation> {
        val v_ = mutableListOf<ContractViolation>()
        ContractCheck.string(v_, path + "/ws_path", wsPath, const = "/api/ws")
        ContractCheck.string(v_, path + "/api_path", apiPath, const = "/api")
        ContractCheck.string(v_, path + "/tls", tls, const = "1")
        ContractCheck.string(v_, path + "/tls_port", tlsPort, rule = ContractCheck.StringRule(pattern = ContractPatterns.P14))
        ContractCheck.string(v_, path + "/fp", fp, rule = ContractCheck.StringRule(pattern = ContractPatterns.P15))
        ContractCheck.string(v_, path + "/pv", pv, rule = ContractCheck.StringRule(pattern = ContractPatterns.P16))
        ContractCheck.string(v_, path + "/pv_min", pvMin, rule = ContractCheck.StringRule(pattern = ContractPatterns.P16))
        val present_ = mutableSetOf<String>()
        present_.add("ws_path")
        present_.add("api_path")
        if (appUrl != null) present_.add("app_url")
        if (tls != null) present_.add("tls")
        if (tlsPort != null) present_.add("tls_port")
        if (fp != null) present_.add("fp")
        present_.add("version")
        present_.add("iid")
        present_.add("pv")
        present_.add("pv_min")
        ContractCheck.obj(v_, path, present_, dependentRequired = mapOf("fp" to listOf("tls_port"), "tls" to listOf("tls_port", "fp")))
        return v_
    }
}

/**
 * Schema: `schemas/bonjour/service.json`.
 */
@Serializable
data class BonjourService(
    @SerialName("service_type") val serviceType: String,
    /**
     * '<home title> (<short id>).' + bonjour_service_type; the short id is the first 6 hex digits of
     * the stable instance id (TXT iid), name conflicts are resolved by mDNS probing.
