        ContractCheck.string(v_, path + "/host", host, rule = ContractCheck.StringRule(pattern = ContractPatterns.P17))
        ContractCheck.long(v_, path + "/port", port, const = 8099L)
        addresses?.forEachIndexed { i0_, x0_ ->
            ContractCheck.string(v_, path + "/addresses" + "/" + i0_, x0_, rule = ContractCheck.StringRule(format = "ipv4"))
        }
        ContractCheck.nested(v_, path + "/txt", txt)
        return v_
    }
}

