/**
 * One entry of the log tab of the hub (GET /api/log): activity (who switched what), change
 * (profile audit, pairing, guests, parent releases, integration starts) or alarm (rejections from
 * a threshold, direct access attempts, integration outages). Names (device, owner, profile) are
 * stored with the entry and replaced by the current name while the device/profile exists. No
 * action data, codes, IP addresses, PINs or tokens.
 * Schema: `schemas/common/log-entry.json`.
 */
@Serializable
data class LogEntry(
    /**
     * Ascending; paging with before_id.
     */
    @SerialName("id") val id: StrictLong,
    @SerialName("ts") val ts: String,
    @SerialName("category") val category: LogEntryCategory,
    /**
     * Fine-grained kind: an event kind of data/events.json, a profile audit action
     * ($defs/profile_audit_action) or a hub kind (device_revoked, kids_release, kids_pause_lifted,
     * integration_dropped, ha_key_withdrawn = the device stopped holding a Home Assistant key
     * (control_path hub without remote access) and the integration has accepted the replacement, so
     * the key the app held no longer works (the hub keeps the device user's new token for the hub
     * path)). device_set_up: detail kind, method (onboard|invite), set_up_by {client_id, name}; actor
     * = name of the setting-up device; texts “Child's iPhone set up by Dad as Child 6–9”.
     * home_networks_set (category change): detail before/after = lists of CIDR. Clients show an
     * unknown kind generically.
     */
    @SerialName("kind") val kind: String,
    @SerialName("event_kind") val eventKind: String?,
    /**
     * ha = HA call_service event of a device user that switches directly (control path direct).
     */
    @SerialName("source") val source: LogEntrySource,
    @SerialName("client_id") val clientId: String?,
    @SerialName("device_name") val deviceName: String?,
    @SerialName("owner_label") val ownerLabel: String?,
    @SerialName("profile_id") val profileId: String?,
    @SerialName("profile_name") val profileName: String?,
    @SerialName("area_id") val areaId: String?,
    @SerialName("area_name") val areaName: String?,
    @SerialName("entity_id") val entityId: String?,
    @SerialName("entity_name") val entityName: String?,
    @SerialName("action") val action: String?,
    @SerialName("route") val route: LogEntryRoute?,
    @SerialName("origin") val origin: LogEntryOrigin?,
    @SerialName("control_path") val controlPath: LogEntryControlPath?,
    @SerialName("result") val result: LogEntryResult?,
    @SerialName("reason") val reason: String?,
    @SerialName("count") val count: StrictLong?,
    @SerialName("since") val since: String?,
    @SerialName("until") val until: String?,
    @SerialName("actor") val actor: String?,
    @SerialName("detail") val detail: JsonObject?,
    @SerialName("device_exists") val deviceExists: StrictBoolean,
    @SerialName("profile_exists") val profileExists: StrictBoolean,
    /**
     * Alarm not marked as read.
     */
    @SerialName("unread") val unread: StrictBoolean,
    /**
     * Entry counts as important: log category alarm, or event_kind/kind marked important in
     * data/events.json. Same rule as the filter important=true of GET /api/log.
     */
    @SerialName("important") val important: StrictBoolean,
) : ContractValue {
    override fun validate(path: String): List<ContractViolation> {
        val v_ = mutableListOf<ContractViolation>()
        ContractCheck.long(v_, path + "/id", id, minimum = 1L)
        ContractCheck.nested(v_, path + "/category", category)
        ContractCheck.string(v_, path + "/kind", kind, rule = ContractCheck.StringRule(pattern = ContractPatterns.P7))
        ContractCheck.string(v_, path + "/event_kind", eventKind, rule = ContractCheck.StringRule(pattern = ContractPatterns.P19))
        ContractCheck.nested(v_, path + "/source", source)
        ContractCheck.string(v_, path + "/client_id", clientId, rule = ContractCheck.StringRule(maxLength = 64))
        ContractCheck.string(v_, path + "/device_name", deviceName, rule = ContractCheck.StringRule(maxLength = 100))
        ContractCheck.string(v_, path + "/owner_label", ownerLabel, rule = ContractCheck.StringRule(maxLength = 50))
        ContractCheck.string(v_, path + "/profile_id", profileId, rule = ContractCheck.StringRule(maxLength = 64))
        ContractCheck.string(v_, path + "/profile_name", profileName, rule = ContractCheck.StringRule(maxLength = 60))
        ContractCheck.string(v_, path + "/area_id", areaId, rule = ContractCheck.StringRule(maxLength = 64))
        ContractCheck.string(v_, path + "/area_name", areaName, rule = ContractCheck.StringRule(maxLength = 100))
        ContractCheck.string(v_, path + "/entity_id", entityId, rule = ContractCheck.StringRule(pattern = ContractPatterns.P3, maxLength = 255))
        ContractCheck.string(v_, path + "/entity_name", entityName, rule = ContractCheck.StringRule(maxLength = 255))
        ContractCheck.string(v_, path + "/action", action, rule = ContractCheck.StringRule(pattern = ContractPatterns.P19))
        ContractCheck.nested(v_, path + "/route", route)
        ContractCheck.nested(v_, path + "/origin", origin)
        ContractCheck.nested(v_, path + "/control_path", controlPath)
        ContractCheck.nested(v_, path + "/result", result)
        ContractCheck.string(v_, path + "/reason", reason, rule = ContractCheck.StringRule(pattern = ContractPatterns.P19))
        ContractCheck.long(v_, path + "/count", count, minimum = 1L)
        ContractCheck.string(v_, path + "/actor", actor, rule = ContractCheck.StringRule(maxLength = 100))
        return v_
    }
}

