    @SerialName("all") val all: StrictBoolean,
    @SerialName("client_ids") val clientIds: List<String>,
) : ContractValue {
    override fun validate(path: String): List<ContractViolation> {
        val v_ = mutableListOf<ContractViolation>()
        ContractCheck.items(v_, path + "/client_ids", clientIds, maxItems = 50, unique = true)
        clientIds.forEachIndexed { i0_, x0_ ->
            ContractCheck.string(v_, path + "/client_ids" + "/" + i0_, x0_, rule = ContractCheck.StringRule(pattern = ContractPatterns.P1))
        }
        return v_
    }
}

/**
 * Family manager: present exactly when rules.family_manager.value is true (never on guests or
 * devices with parental controls). children is the current scope as a short list for the tab
 * “Family”; details come with family_get_children. remote: away = family functions also work away
 * from home through Home Assistant and the integration relay (needs effective remote access),
 * home_only = only in the home network. Changes of scope, children, notify settings or remote send
 * client_config_updated.
 * Schema: `schemas/common/client-family.json`.
 */
@Serializable
data class ClientFamily(
    @SerialName("scope") val scope: FamilyChildrenScope,
    @SerialName("children") val children: List<ClientFamilyChildrenItem>,
    @SerialName("open_requests") val openRequests: StrictLong,
    /**
     * Automatic child notifications of this device (data/family.json notify_defaults;
     * kids_release_requested always true).
     */
    @SerialName("notify") val notify: JsonObject,
    /**
     * Home Assistant notify services the admin linked to this family manager (requests arrive even
     * with the app closed; actionable for mobile_app targets). Display only.
     */
    @SerialName("notify_targets") val notifyTargets: List<String>? = null,
    @SerialName("remote") val remote: ClientFamilyRemote,
) : ContractValue {
    override fun validate(path: String): List<ContractViolation> {
        val v_ = mutableListOf<ContractViolation>()
        ContractCheck.nested(v_, path + "/scope", scope)
        ContractCheck.items(v_, path + "/children", children, maxItems = 50)
        ContractCheck.nested(v_, path + "/children", children)
        ContractCheck.long(v_, path + "/open_requests", openRequests, minimum = 0L)
        ContractCheck.items(v_, path + "/notify_targets", notifyTargets, maxItems = 5)
        notifyTargets?.forEachIndexed { i0_, x0_ ->
            ContractCheck.string(v_, path + "/notify_targets" + "/" + i0_, x0_, rule = ContractCheck.StringRule(pattern = ContractPatterns.P24))
        }
        ContractCheck.nested(v_, path + "/remote", remote)
        return v_
    }
}

@Serializable
data class ClientKidsRequestsRecipientsItem(
    /**
     * First name (owner label), else the device name.
     */
    @SerialName("name") val name: String,
    /**
     * family_manager or babysitter ($defs/family_actor_kind).
