/**
 * “Can I have more time?”: a child device asks its family managers (and the admin). One open
 * request per child device. answer is set exactly for approved/declined. The child sees only
 * status, answer.answer/until/message and the first name of who answered; family managers and the
 * admin see everything. Babysitters (kind babysitter, rule babysitter_requests) receive open
 * requests while they have access and are at home; answer.by.kind babysitter names them for the
 * parents.
 * Schema: `schemas/common/family-request.json`.
 */
@Serializable
data class FamilyRequest(
    @SerialName("request_id") val requestId: String,
    @SerialName("client_id") val clientId: String,
    /**
     * Device name of the child device.
     */
    @SerialName("child_name") val childName: String,
    @SerialName("owner_label") val ownerLabel: String? = null,
    @SerialName("category") val category: FamilyRequestCategory,
    @SerialName("entity_id") val entityId: String? = null,
    @SerialName("entity_name") val entityName: String? = null,
    @SerialName("note") val note: String? = null,
    @SerialName("status") val status: FamilyRequestStatus,
    @SerialName("created_at") val createdAt: String,
    @SerialName("expires_at") val expiresAt: String,
    /**
     * For family managers: true = a Yes is allowed for this device (no fixed rule in the way). false:
     * the app disables Yes and says that only the admin can allow it.
     */
    @SerialName("can_approve") val canApprove: StrictBoolean? = null,
    /**
     * Only in requests sent to a babysitter: the durations it may give with a Yes (15m, 30m and
     * access_end while its access has a known end). Babysitters get no note of the child's earlier
     * requests and no rules.
     */
    @SerialName("answer_presets") val answerPresets: List<FamilyReleasePreset>? = null,
    @SerialName("answer") val answer: FamilyRequestAnswer?,
) : ContractValue {
    override fun validate(path: String): List<ContractViolation> {
        val v_ = mutableListOf<ContractViolation>()
        ContractCheck.string(v_, path + "/request_id", requestId, rule = ContractCheck.StringRule(pattern = ContractPatterns.P1))
        ContractCheck.string(v_, path + "/client_id", clientId, rule = ContractCheck.StringRule(pattern = ContractPatterns.P1))
        ContractCheck.string(v_, path + "/child_name", childName, rule = ContractCheck.StringRule(maxLength = 100))
        ContractCheck.string(v_, path + "/owner_label", ownerLabel, rule = ContractCheck.StringRule(maxLength = 50))
        ContractCheck.nested(v_, path + "/category", category)
        ContractCheck.string(v_, path + "/entity_id", entityId, rule = ContractCheck.StringRule(pattern = ContractPatterns.P3, maxLength = 255))
        ContractCheck.string(v_, path + "/entity_name", entityName, rule = ContractCheck.StringRule(maxLength = 255))
        ContractCheck.string(v_, path + "/note", note, rule = ContractCheck.StringRule(maxLength = 80))
        ContractCheck.nested(v_, path + "/status", status)
        ContractCheck.items(v_, path + "/answer_presets", answerPresets, unique = true)
        ContractCheck.nested(v_, path + "/answer_presets", answerPresets)
        ContractCheck.nested(v_, path + "/answer", answer)
        val present_ = mutableSetOf<String>()
        present_.add("request_id")
        present_.add("client_id")
        present_.add("child_name")
        if (ownerLabel != null) present_.add("owner_label")
        present_.add("category")
        if (entityId != null) present_.add("entity_id")
        if (entityName != null) present_.add("entity_name")
        if (note != null) present_.add("note")
        present_.add("status")
        present_.add("created_at")
        present_.add("expires_at")
        if (canApprove != null) present_.add("can_approve")
        if (answerPresets != null) present_.add("answer_presets")
        if (answer != null) present_.add("answer")
        val c0_ = category.value in listOf("unlock_device")
        ContractCheck.obj(v_, path, present_, conditionals = listOf(ContractCheck.Conditional(c0_, listOf("entity_id"), listOf(), listOf(), listOf())))
        return v_
    }
}

/**
 * “Can I have more time?” on a child device. enabled = at least one family manager of this child
 * or an admin notification target for kids_release_requested exists and the admin did not switch
 * requests off; otherwise the app hides the button. open = own open request (also after a restart
 * of the app). next_allowed_at = cooldown after a No or the hourly limit. recipients = who gets a
 * request right now: the hub sends client_config_updated to the child whenever the list changes (a
 * babysitter's access opens or closes, it connects or leaves, a rename).
 * Schema: `schemas/common/client-kids-requests.json`.
 */
@Serializable
data class ClientKidsRequests(
    @SerialName("enabled") val enabled: StrictBoolean,
    @SerialName("categories") val categories: List<FamilyRequestCategory>,
    @SerialName("open") val open: FamilyRequest?,
    @SerialName("next_allowed_at") val nextAllowedAt: String?,
    /**
     * Who gets a request of this child now, for “Dad and Mum will get your question.”: every family
     * manager of the child (role family_manager) and every active babysitter (role babysitter: rule
     * babysitter_requests, access open right now, connected to the hub = at home; docs/access.md).
     * Family managers first, then babysitters, each sorted by name; the same name only once per role.
     * Empty = nobody can answer by name (the app says “a grown-up”).
     */
    @SerialName("recipients") val recipients: List<ClientKidsRequestsRecipientsItem>,
) : ContractValue {
    override fun validate(path: String): List<ContractViolation> {
        val v_ = mutableListOf<ContractViolation>()
        ContractCheck.items(v_, path + "/categories", categories, unique = true)
        ContractCheck.nested(v_, path + "/categories", categories)
        ContractCheck.nested(v_, path + "/open", open)
        ContractCheck.items(v_, path + "/recipients", recipients, maxItems = 10)
        ContractCheck.nested(v_, path + "/recipients", recipients)
        return v_
    }
}

/**
 * Rate limit per entity and device: more than max_actions successful actions within window_seconds
 * start a pause of cooldown_seconds for this entity (0 = no pause, free again when the oldest
 * action leaves the window). Rejected attempts do not count.
 */
@Serializable
data class KidsRateLimit(
    @SerialName("max_actions") val maxActions: StrictLong,
    @SerialName("window_seconds") val windowSeconds: StrictLong,
    @SerialName("cooldown_seconds") val cooldownSeconds: StrictLong,
) : ContractValue {
    override fun validate(path: String): List<ContractViolation> {
        val v_ = mutableListOf<ContractViolation>()
        ContractCheck.long(v_, path + "/max_actions", maxActions, minimum = 1L, maximum = 100L)
        ContractCheck.long(v_, path + "/window_seconds", windowSeconds, minimum = 5L, maximum = 3600L)
        ContractCheck.long(v_, path + "/cooldown_seconds", cooldownSeconds, minimum = 0L, maximum = 86400L)
        return v_
    }
}

/**
 * Bedtime window. end <= start crosses midnight and belongs to the start day (fri 21:00-07:00 ends
 * Saturday 07:00); start == end = the whole day. During a window only reducing actions are allowed
 * (turn_off, toggle of a device that is on, media_pause, media_stop, volume_down, volume_mute with
 * is_volume_muted true, close_cover, stop_cover).
 */
@Serializable
data class QuietHoursWindow(
    @SerialName("days") val days: List<KidsWeekday>,
    @SerialName("start") val start: String,
    @SerialName("end") val end: String,
) : ContractValue {
    override fun validate(path: String): List<ContractViolation> {
        val v_ = mutableListOf<ContractViolation>()
        ContractCheck.items(v_, path + "/days", days, minItems = 1, maxItems = 7, unique = true)
        ContractCheck.nested(v_, path + "/days", days)
        ContractCheck.string(v_, path + "/start", start, rule = ContractCheck.StringRule(pattern = ContractPatterns.P2))
        ContractCheck.string(v_, path + "/end", end, rule = ContractCheck.StringRule(pattern = ContractPatterns.P2))
        return v_
    }
}

/**
 * Rule object of the kids mode, the same on the levels profile, area and entity. A missing field
 * is inherited from the more general level (entity -> area -> profile); null for
 * rate_limit/volume_max switches the rule off on that level. Access: entity blocked, else area
 * blocked, else effective blocked_types (area, else profile), else profile blocked. An entity
 * placed in several visible areas is checked per area; any block wins. blocked_types is not
 * allowed on the entity level (422 rules.blocked_types). Invalid objects: 422 with detail
 * rules.<field>.
 * Schema: `schemas/common/kids-rules.json`.
 */
@Serializable
data class KidsRules(
    /**
     * true = everything in this scope blocked; false = explicitly allowed (overrides blocked_types and
     * blocked of the more general levels).
     */
    @SerialName("blocked") val blocked: StrictBoolean? = null,
    /**
     * Profile and area only; on the area level it replaces the profile's list.
     */
    @SerialName("blocked_types") val blockedTypes: List<String>? = null,
    /**
     * Bedtime windows; [] = no bedtime on this level (exception, e.g. a night light).
     */
    @SerialName("quiet_hours") val quietHours: List<QuietHoursWindow>? = null,
    @SerialName("rate_limit") val rateLimit: KidsRateLimit? = null,
    /**
     * Lights: no rgb/rgbw/rgbww/hs/xy color, color_name, effect, flash. On/off, brightness and
     * color_temp_kelvin stay allowed.
     */
    @SerialName("color_lock") val colorLock: StrictBoolean? = null,
    /**
     * Volume cap in percent for media_player: volume_set above it is set to the cap (answer adjusted),
     * volume_up at the cap is rejected (volume_limit), just below it becomes volume_set(cap); unknown
     * volume rejects volume_up.
     */
    @SerialName("volume_max") val volumeMax: StrictLong? = null,
) : ContractValue {
    override fun validate(path: String): List<ContractViolation> {
        val v_ = mutableListOf<ContractViolation>()
        ContractCheck.items(v_, path + "/blocked_types", blockedTypes, maxItems = 30, unique = true)
        blockedTypes?.forEachIndexed { i0_, x0_ ->
            ContractCheck.string(v_, path + "/blocked_types" + "/" + i0_, x0_, rule = ContractCheck.StringRule(pattern = ContractPatterns.P25))
        }
        ContractCheck.items(v_, path + "/quiet_hours", quietHours, maxItems = 14)
        ContractCheck.nested(v_, path + "/quiet_hours", quietHours)
        ContractCheck.nested(v_, path + "/rate_limit", rateLimit)
        ContractCheck.long(v_, path + "/volume_max", volumeMax, minimum = 0L, maximum = 100L)
        return v_
    }
}

@Serializable
data class ClientKidsRules(
    @SerialName("profile") val profile: KidsRules,
    /**
     * area_id -> rules.
     */
    @SerialName("areas") val areas: JsonObject,
    /**
     * entity_id -> rules.
     */
    @SerialName("entities") val entities: JsonObject,
) : ContractValue {
    override fun validate(path: String): List<ContractViolation> {
        val v_ = mutableListOf<ContractViolation>()
        ContractCheck.nested(v_, path + "/profile", profile)
        return v_
    }
}

/**
 * Running release: until `until` the rule(s) of kind do not apply on this child device. bedtime:
 * kids_quiet_hours; pause: kids_rate_limit and running pauses; entity: blocked type and bedtime
 * for entity_id (never locks/alarm panels or entities blocked in kids_exceptions). Ends at until
 * (hub planner), by release_end or when the device loses parental controls. At most one release
 * per kind (and per entity).
 * Schema: `schemas/common/family-release.json`.
 */
@Serializable
data class FamilyRelease(
    @SerialName("kind") val kind: FamilyReleaseKind,
    @SerialName("entity_id") val entityId: String? = null,
    @SerialName("until") val until: String,
    @SerialName("by") val by: FamilyActor,
    @SerialName("request_id") val requestId: String? = null,
    @SerialName("created_at") val createdAt: String,
) : ContractValue {
    override fun validate(path: String): List<ContractViolation> {
        val v_ = mutableListOf<ContractViolation>()
        ContractCheck.nested(v_, path + "/kind", kind)
        ContractCheck.string(v_, path + "/entity_id", entityId, rule = ContractCheck.StringRule(pattern = ContractPatterns.P3, maxLength = 255))
        ContractCheck.nested(v_, path + "/by", by)
        ContractCheck.string(v_, path + "/request_id", requestId, rule = ContractCheck.StringRule(pattern = ContractPatterns.P1))
        val present_ = mutableSetOf<String>()
        present_.add("kind")
        if (entityId != null) present_.add("entity_id")
        present_.add("until")
        present_.add("by")
        if (requestId != null) present_.add("request_id")
        present_.add("created_at")
        val c0_ = kind.value in listOf("entity")
        ContractCheck.obj(v_, path, present_, conditionals = listOf(ContractCheck.Conditional(c0_, listOf("entity_id"), listOf(), listOf(), listOf())))
        return v_
    }
}

/**
 * Kids mode of a device with parental controls. Present exactly when profile.child_protection is
 * true. The hub enforces the rules where it is reachable, the integration (<ns>.control) when away
 * is ha; rules is for display (grey out, limit sliders, countdown). rules.profile mirrors the
 * effective kids_* rules (client_config.rules), rules.areas and rules.entities the profile's
 * kids_exceptions with the own area resolved.
 * Schema: `schemas/common/client-kids.json`.
 */
@Serializable
data class ClientKids(
    /**
     * Control path at home: only through the hub (WS control).
     */
    @SerialName("control") val control: String,
    /**
     * How the device controls while the hub is not reachable. none = not at all (no HA key on the
     * device, ha_token null: rule control_path hub without remote access). ha = the device holds a
     * read-only HA key (rule control_path checked, or hub with effective remote_access; ha_token while
     * the access is open, ha_enforcement.control_path checked) and, while the hub is not reachable,
     * reads states and history from Home Assistant and switches only through <ns>.control, where the
     * integration enforces every kids rule (bedtime, blocked types, color lock, volume cap, releases;
     * pauses and the pause of everything asked from the hub, kids-check). Requests (“Can I have more
     * time?”) go through <ns>/family. Where the hub is reachable it stays the control path.
     */
    @SerialName("away") val away: ClientKidsAway,
    /**
     * IANA zone of the bedtime windows (Home Assistant's time_zone); null = UTC.
     */
    @SerialName("time_zone") val timeZone: String?,
    /**
     * Parent release: until then bedtime, rate limit and pauses do not apply (blocked types, color
     * lock and volume cap do). null = no release.
     */
    @SerialName("override_until") val overrideUntil: String?,
    /**
     * Everything is paused until then (overall rate limit kids_rate_limit_all exceeded); the hub
     * rejects every action with rule_blocked {reason paused_all, until}. The app may grey out all
     * controls and show the end time; it switches back at until even offline. Missing or null = no
     * pause of everything. The hub sends client_config_updated when such a pause starts or is ended
     * early (release, admin).
     */
    @SerialName("paused_all_until") val pausedAllUntil: String? = null,
    @SerialName("rules") val rules: ClientKidsRules,
    /**
     * Running releases by the admin or a family manager; the app shows them (“Up until 21:00”) and
     * switches back at until even offline. Missing = none.
     */
    @SerialName("releases") val releases: List<FamilyRelease>? = null,
    @SerialName("requests") val requests: ClientKidsRequests? = null,
) : ContractValue {
    override fun validate(path: String): List<ContractViolation> {
        val v_ = mutableListOf<ContractViolation>()
        ContractCheck.string(v_, path + "/control", control, const = "hub")
        ContractCheck.nested(v_, path + "/away", away)
        ContractCheck.string(v_, path + "/time_zone", timeZone, rule = ContractCheck.StringRule(maxLength = 64))
        ContractCheck.nested(v_, path + "/rules", rules)
        ContractCheck.nested(v_, path + "/releases", releases)
        ContractCheck.nested(v_, path + "/requests", requests)
        return v_
    }
}

/**
 * Profile of the device. Every device has exactly one profile; the app shows its name (“Managed by
 * {managed_by} · Profile: {name}”). child_protection = parental controls: the device is on the hub
 * path and controls through the hub where it is reachable (WS control, POST /api/client/control);
 * when it holds a key (rule control_path checked, or hub with remote access) it uses it while the
 * hub is not reachable (<ns>.control, client_config.kids.away ha), otherwise it has no HA key
 * (ha_token and ha_url null); client_config.kids carries the rules. A change of the profile, its
 * rules, a device adjustment or its expiry sends client_config_updated.
 * Schema: `schemas/common/client-profile.json`.
 */
@Serializable
data class ClientProfile(
    @SerialName("id") val id: String,
    @SerialName("name") val name: String,
    /**
     * Kind of the profile: the app starts accordingly (child view, wall panel, TV kiosk) only through
     * the rules; the kind itself changes no rule.
     */
    @SerialName("kind") val kind: ProfileKind,
    /**
     * Revision of the profile; increases with every saved change.
     */
    @SerialName("rev") val rev: StrictLong,
    /**
     * Parental controls.
     */
    @SerialName("child_protection") val childProtection: StrictBoolean,
    /**
     * Display name of the hub admin (Home Assistant owner) for texts on the device; null = unknown.
     */
    @SerialName("managed_by") val managedBy: String? = null,
) : ContractValue {
    override fun validate(path: String): List<ContractViolation> {
        val v_ = mutableListOf<ContractViolation>()
        ContractCheck.string(v_, path + "/id", id, rule = ContractCheck.StringRule(pattern = ContractPatterns.P1))
        ContractCheck.string(v_, path + "/name", name, rule = ContractCheck.StringRule(pattern = ContractPatterns.P26, minLength = 1, maxLength = 40))
        ContractCheck.nested(v_, path + "/kind", kind)
        ContractCheck.long(v_, path + "/rev", rev, minimum = 1L)
        ContractCheck.string(v_, path + "/managed_by", managedBy, rule = ContractCheck.StringRule(maxLength = 100))
        return v_
    }
}

/**
 * Access hours: effective value with its source (generated by tools/profile_rules.py).
 */
@Serializable
data class ResolvedRulesAccessHours(
    @SerialName("value") val value: AccessHours,
    @SerialName("source") val source: RuleSource,
    @SerialName("reason") val reason: RuleReason,
    /**
     * true = the person at the device must not change the value (everything except user_choice).
     */
    @SerialName("locked") val locked: StrictBoolean,
    /**
     * true = the admin cannot adjust the rule on this device (profile checkbox “Fixed”, or decided by
     * a boundary). Display only.
     */
    @SerialName("fixed") val fixed: StrictBoolean,
    /**
     * true = the person at the device decides; value is the starting value and replaces nothing the
     * person chose locally. Missing = false.
     */
    @SerialName("user_choice") val userChoice: StrictBoolean? = null,
    /**
     * Temporary device adjustment: end (UTC). The app switches to then at this time even offline; the
     * hub sends client_config_updated.
     */
    @SerialName("expires_at") val expiresAt: String? = null,
    /**
     * Value after expires_at (only with expires_at).
     */
    @SerialName("then") val then: AccessHours? = null,
    /**
     * Display name of who set the device adjustment (admin or family manager device); only with source
     * device. Apps use it instead of {admin} in the reason sentence.
     */
    @SerialName("set_by") val setBy: String? = null,
    /**
     * Who enforces it on this device: ha/hub = show “Enforced”, app = “Applies in <brand>”.
     */
    @SerialName("enforcement") val enforcement: RuleEnforcement? = null,
) : ContractValue {
    override fun validate(path: String): List<ContractViolation> {
        val v_ = mutableListOf<ContractViolation>()
        ContractCheck.nested(v_, path + "/value", value)
        ContractCheck.nested(v_, path + "/source", source)
        ContractCheck.nested(v_, path + "/reason", reason)
        ContractCheck.nested(v_, path + "/then", then)
        ContractCheck.string(v_, path + "/set_by", setBy, rule = ContractCheck.StringRule(maxLength = 100))
        ContractCheck.nested(v_, path + "/enforcement", enforcement)
        return v_
    }
}

/**
 * Ask for early access: effective value with its source (generated by tools/profile_rules.py).
 */
@Serializable
data class ResolvedRulesAccessRequests(
    @SerialName("value") val value: StrictBoolean,
    @SerialName("source") val source: RuleSource,
    @SerialName("reason") val reason: RuleReason,
    /**
     * true = the person at the device must not change the value (everything except user_choice).
     */
    @SerialName("locked") val locked: StrictBoolean,
    /**
     * true = the admin cannot adjust the rule on this device (profile checkbox “Fixed”, or decided by
     * a boundary). Display only.
     */
    @SerialName("fixed") val fixed: StrictBoolean,
    /**
     * true = the person at the device decides; value is the starting value and replaces nothing the
     * person chose locally. Missing = false.
     */
