/**
 * Visible areas. all = every active area; selected = the listed areas, areas with one of the tags
 * and (own_area) the device's own area; nothing selected = no area (fail closed). In resolved
 * values (client_config) the hub has replaced own_area by the concrete id: own_area is always
 * false there.
 */
@Serializable
data class ProfileRuleValuesAreas(
    @SerialName("mode") val mode: ProfileRuleValuesAreasMode,
    @SerialName("area_ids") val areaIds: List<String>? = null,
    @SerialName("tags") val tags: List<String>? = null,
    @SerialName("own_area") val ownArea: StrictBoolean? = null,
) : ContractValue {
    override fun validate(path: String): List<ContractViolation> {
        val v_ = mutableListOf<ContractViolation>()
        ContractCheck.nested(v_, path + "/mode", mode)
        ContractCheck.items(v_, path + "/area_ids", areaIds, maxItems = 200, unique = true)
        areaIds?.forEachIndexed { i0_, x0_ ->
            ContractCheck.string(v_, path + "/area_ids" + "/" + i0_, x0_, rule = ContractCheck.StringRule(pattern = ContractPatterns.P1))
        }
        ContractCheck.items(v_, path + "/tags", tags, maxItems = 50, unique = true)
        tags?.forEachIndexed { i0_, x0_ ->
            ContractCheck.string(v_, path + "/tags" + "/" + i0_, x0_, rule = ContractCheck.StringRule(pattern = ContractPatterns.P6, minLength = 1, maxLength = 50))
        }
        return v_
    }
}

