/**
 * Overall rate limit of a child device (failsafe next to the rate limit per entity): when the
 * child switches more than max_entities different entities or more than max_actions actions in
 * total within window_seconds, everything pauses for cooldown_seconds (every entity of the device,
 * hub path and <ns>.control alike). The action that would exceed a limit is rejected and starts
 * the pause (reason paused_all with until). Successful actions count, rejected attempts do not.
 * enabled false = off (the values are kept so switching on restores them). A parental release
 * (override_until) and the family release kind pause end a running pause and suspend the limit
 * until they end.
 */
@Serializable
data class KidsRateLimitAll(
    @SerialName("enabled") val enabled: StrictBoolean,
    /**
     * Actions in total within the window; one more starts the pause.
     */
    @SerialName("max_actions") val maxActions: StrictLong,
    /**
     * Different entities within the window; one more starts the pause.
     */
    @SerialName("max_entities") val maxEntities: StrictLong,
    @SerialName("window_seconds") val windowSeconds: StrictLong,
    /**
     * Length of the pause of everything.
     */
    @SerialName("cooldown_seconds") val cooldownSeconds: StrictLong,
) : ContractValue {
    override fun validate(path: String): List<ContractViolation> {
        val v_ = mutableListOf<ContractViolation>()
        ContractCheck.long(v_, path + "/max_actions", maxActions, minimum = 1L, maximum = 200L)
        ContractCheck.long(v_, path + "/max_entities", maxEntities, minimum = 1L, maximum = 50L)
        ContractCheck.long(v_, path + "/window_seconds", windowSeconds, minimum = 10L, maximum = 3600L)
        ContractCheck.long(v_, path + "/cooldown_seconds", cooldownSeconds, minimum = 30L, maximum = 86400L)
        return v_
    }
}

