    override fun validate(path: String): List<ContractViolation> {
        val v_ = mutableListOf<ContractViolation>()
        ContractCheck.nested(v_, path + "/mode", mode)
        ContractCheck.long(v_, path + "/level", level, minimum = 5L, maximum = 100L)
        ContractCheck.string(v_, path + "/lux_entity", luxEntity, rule = ContractCheck.StringRule(pattern = ContractPatterns.P27, maxLength = 255))
        ContractCheck.long(v_, path + "/min", min, minimum = 5L, maximum = 100L)
        ContractCheck.long(v_, path + "/max", max, minimum = 5L, maximum = 100L)
        ContractCheck.long(v_, path + "/lux_max", luxMax, minimum = 10L, maximum = 100000L)
        ContractCheck.nested(v_, path + "/curve", curve)
        ContractCheck.items(v_, path + "/schedule", schedule, minItems = 1, maxItems = 8)
        ContractCheck.nested(v_, path + "/schedule", schedule)
        val present_ = mutableSetOf<String>()
        present_.add("mode")
        if (level != null) present_.add("level")
        if (luxEntity != null) present_.add("lux_entity")
        if (min != null) present_.add("min")
        if (max != null) present_.add("max")
        if (luxMax != null) present_.add("lux_max")
        if (curve != null) present_.add("curve")
        if (schedule != null) present_.add("schedule")
        val c0_ = mode.value in listOf("fixed")
        val c1_ = mode.value in listOf("lux")
        val c2_ = mode.value in listOf("device_lux")
        val c3_ = mode.value in listOf("schedule")
        ContractCheck.obj(v_, path, present_, conditionals = listOf(ContractCheck.Conditional(c0_, listOf("level"), listOf(), listOf(), listOf()), ContractCheck.Conditional(c1_, listOf("lux_entity", "min", "max"), listOf(), listOf(), listOf()), ContractCheck.Conditional(c2_, listOf("min", "max"), listOf(), listOf(), listOf()), ContractCheck.Conditional(c3_, listOf("schedule"), listOf(), listOf(), listOf())))
