        ContractCheck.double(v_, path + "/speed", speed, minimum = 0.0, maximum = 1000.0)
        ContractCheck.double(v_, path + "/course", course, minimum = 0.0, maximum = 360.0)
        ContractCheck.long(v_, path + "/battery_level", batteryLevel, minimum = 0L, maximum = 100L)
        ContractCheck.string(v_, path + "/ts", ts, rule = ContractCheck.StringRule(format = "date-time"))
        ContractCheck.nested(v_, path + "/location_shared", locationShared)
