        ContractCheck.string(v_, path + "/type", type, const = TYPE)
        ContractCheck.string(v_, path + "/public_key", publicKey, rule = ContractCheck.StringRule(pattern = ContractPatterns.P36))
        ContractCheck.string(v_, path + "/client_name", clientName, rule = ContractCheck.StringRule(minLength = 1, maxLength = 100))
        ContractCheck.long(v_, path + "/protocol_version", protocolVersion, minimum = 1L)
        ContractCheck.nested(v_, path + "/platform", platform)
        ContractCheck.string(v_, path + "/app_version", appVersion, rule = ContractCheck.StringRule(pattern = ContractPatterns.P21, maxLength = 32))
        ContractCheck.string(v_, path + "/app_build", appBuild, rule = ContractCheck.StringRule(pattern = ContractPatterns.P22))
        ContractCheck.string(v_, path + "/device_model", deviceModel, rule = ContractCheck.StringRule(pattern = ContractPatterns.P20))
        return v_
