/**
 * Real-time notification push (POST /api/notifications, POST /api/integration/notify). Fields as
 * notification item without status. A notification for a watch is pushed to the phone that set it
 * up (client_id is the phone's); the phone's system shows it on the watch.
 * Schema: `schemas/ws/command/display_notification.json`.
 */
@Serializable
data class CommandDisplayNotification(
    @EncodeDefault @SerialName("type") val type: String = TYPE,
    @EncodeDefault @SerialName("command") val command: String = COMMAND,
    @SerialName("notification_id") val notificationId: String,
    @SerialName("title") val title: String,
    @SerialName("message") val message: String? = null,
    /**
     * Canonical values; the hub also accepts normal and permanent and stores their canonical value.
     */
    @SerialName("notification_type") val notificationType: NotificationItemNotificationType,
    /**
     * Derived: true exactly when popup_mode is not 'none'.
     */
    @SerialName("popup") val popup: StrictBoolean,
    @SerialName("popup_mode") val popupMode: NotificationItemPopupMode,
    /**
     * ISO 8601; the app schedules a local notification, delivery is immediate.
     */
    @SerialName("scheduled_at") val scheduledAt: String? = null,
    @SerialName("priority") val priority: StrictLong,
    @SerialName("color") val color: NotificationItemColor,
    @SerialName("action_type") val actionType: NotificationItemActionType,
    @SerialName("action_target") val actionTarget: String? = null,
    @SerialName("show_time") val showTime: StrictBoolean,
    @SerialName("created_at") val createdAt: String? = null,
    /**
     * Present in the notifications list and the HA sensor, absent in display_notification.
     */
    @SerialName("status") val status: NotificationItemStatus? = null,
    /**
     * Only present when set.
     */
    @SerialName("icon") val icon: String? = null,
    /**
     * Only present when set. Not decoded by the apps (known deviation D1, docs/protocol.md).
     */
    @SerialName("icon_svg") val iconSvg: String? = null,
) : ContractValue, ServerMessage {
    companion object {
        const val TYPE: String = "command"
        const val COMMAND: String = "display_notification"
    }

    override fun validate(path: String): List<ContractViolation> {
        val v_ = mutableListOf<ContractViolation>()
        ContractCheck.string(v_, path + "/type", type, const = TYPE)
        ContractCheck.string(v_, path + "/command", command, const = COMMAND)
        ContractCheck.string(v_, path + "/notification_id", notificationId, rule = ContractCheck.StringRule(pattern = ContractPatterns.P1))
        ContractCheck.string(v_, path + "/title", title, rule = ContractCheck.StringRule(maxLength = 500))
        ContractCheck.string(v_, path + "/message", message, rule = ContractCheck.StringRule(maxLength = 5000))
        ContractCheck.nested(v_, path + "/notification_type", notificationType)
        ContractCheck.nested(v_, path + "/popup_mode", popupMode)
        ContractCheck.long(v_, path + "/priority", priority, minimum = 0L, maximum = 100L)
        ContractCheck.nested(v_, path + "/color", color)
        ContractCheck.nested(v_, path + "/action_type", actionType)
        ContractCheck.string(v_, path + "/action_target", actionTarget, rule = ContractCheck.StringRule(maxLength = 2000))
        ContractCheck.nested(v_, path + "/status", status)
        ContractCheck.string(v_, path + "/icon_svg", iconSvg, rule = ContractCheck.StringRule(maxLength = 10000))
        val present_ = mutableSetOf<String>()
        present_.add("notification_id")
        present_.add("title")
        if (message != null) present_.add("message")
        present_.add("notification_type")
        present_.add("popup")
        present_.add("popup_mode")
        if (scheduledAt != null) present_.add("scheduled_at")
        present_.add("priority")
        present_.add("color")
        present_.add("action_type")
        if (actionTarget != null) present_.add("action_target")
        present_.add("show_time")
        if (createdAt != null) present_.add("created_at")
        if (status != null) present_.add("status")
        if (icon != null) present_.add("icon")
        if (iconSvg != null) present_.add("icon_svg")
        ContractCheck.obj(v_, path, present_, forbidden = listOf("status"))
        return v_
    }
}

