 * Per-client compliance status. sig only for restricting statuses; see
 * fixtures/crypto/compliance-vectors. need_token_update: device deactivated, guest past its
 * expiry, or the device's HA token changed after its last contact with the hub (ha_token_minted_at
 * > last_seen: rotated or remote access switched off while the device was away). The app stops
 * signing in to HA from outside until it is home again (HA IP ban). deleted: pending deletion.
 * Schema: `schemas/common/compliance-blob.json`.
 */
@Serializable
data class ComplianceBlob(
    @SerialName("status") val status: ComplianceBlobStatus,
    /**
     * Unix seconds. The app does not check its age; a replayed signed status can only repeat a
     * restricting status for the same device (docs/enforcement.md, Compliance status away from home).
     */
    @SerialName("ts") val ts: StrictLong,
    @SerialName("sig") val sig: String? = null,
) : ContractValue {
    override fun validate(path: String): List<ContractViolation> {
        val v_ = mutableListOf<ContractViolation>()
        ContractCheck.nested(v_, path + "/status", status)
        ContractCheck.string(v_, path + "/sig", sig, rule = ContractCheck.StringRule(pattern = ContractPatterns.P15))
        val present_ = mutableSetOf<String>()
        present_.add("status")
        present_.add("ts")
        if (sig != null) present_.add("sig")
        val c0_ = status.value in listOf("need_token_update", "deleted")
        val c1_ = status.value in listOf("compliant", "unknown")
        ContractCheck.obj(v_, path, present_, conditionals = listOf(ContractCheck.Conditional(c0_, listOf(), listOf(), listOf(), listOf()), ContractCheck.Conditional(c1_, listOf(), listOf("sig"), listOf(), listOf())))
        return v_
    }
}

