        ContractCheck.nested(v_, path + "/boundaries", boundaries)
        ContractCheck.items(v_, path + "/profile_kinds", profileKinds, minItems = 1)
        ContractCheck.nested(v_, path + "/profile_kinds", profileKinds)
        ContractCheck.nested(v_, path + "/reasons", reasons)
        ContractCheck.nested(v_, path + "/expiry_presets", expiryPresets)
