/**
 * One structured event of the integration for the log tab of the hub (activity and alarms). Data
 * minimization: only the fields below; never action data (no values, no codes), no IP addresses,
 * no names (the hub knows the device by client_id).
 * Schema: `schemas/common/enforcement-event.json`.
 */
@Serializable
data class EnforcementEvent(
    /**
     * Random id; the hub ignores a repeated id (retry after a timeout).
     */
    @SerialName("id") val id: String,
    @SerialName("type") val type: EnforcementEventType,
    /**
     * UTC, when it happened (not when it was sent).
     */
    @SerialName("at") val at: String,
    @SerialName("client_id") val clientId: String? = null,
    /**
     * Set when the device is not known (direct_access_attempt of a user without mapping never happens:
     * such users are ignored).
     */
    @SerialName("ha_user_id") val haUserId: String? = null,
    @SerialName("entity_id") val entityId: String? = null,
    @SerialName("action") val action: String? = null,
    @SerialName("route") val route: ControlRoute? = null,
    @SerialName("origin") val origin: ControlOrigin? = null,
    /**
     * denied: why; control: null.
     */
    @SerialName("reason") val reason: ControlDenialReason? = null,
    /**
     * Occurrences merged into this event (direct_access_attempt: rejected direct actions in the
     * window). Missing = 1.
     */
    @SerialName("count") val count: StrictLong? = null,
    /**
     * integration_outage: last sign of life before the gap; direct_access_attempt: first attempt in
     * the window.
     */
    @SerialName("since") val since: String? = null,
    /**
     * rules_applied, access_group_restored: group the device user has now.
     */
    @SerialName("ha_group") val haGroup: HaUserGroup? = null,
    /**
     * rules_applied: the snapshot now in force.
     */
    @SerialName("rules_hash") val rulesHash: String? = null,
    /**
     * best_effort = detected on a best-effort basis (direct_access_attempt, integration_outage); may
     * miss occurrences. Missing = exact.
     */
    @SerialName("reliability") val reliability: EnforcementEventReliability? = null,
    /**
     * integration_started: version of the integration.
     */
    @SerialName("version") val version: String? = null,
) : ContractValue {
    override fun validate(path: String): List<ContractViolation> {
        val v_ = mutableListOf<ContractViolation>()
        ContractCheck.string(v_, path + "/id", id, rule = ContractCheck.StringRule(pattern = ContractPatterns.P1))
        ContractCheck.nested(v_, path + "/type", type)
        ContractCheck.string(v_, path + "/client_id", clientId, rule = ContractCheck.StringRule(pattern = ContractPatterns.P1))
        ContractCheck.string(v_, path + "/ha_user_id", haUserId, rule = ContractCheck.StringRule(pattern = ContractPatterns.P29))
        ContractCheck.string(v_, path + "/entity_id", entityId, rule = ContractCheck.StringRule(pattern = ContractPatterns.P3, maxLength = 255))
        ContractCheck.string(v_, path + "/action", action, rule = ContractCheck.StringRule(pattern = ContractPatterns.P19))
        ContractCheck.nested(v_, path + "/route", route)
        ContractCheck.nested(v_, path + "/origin", origin)
        ContractCheck.nested(v_, path + "/reason", reason)
        ContractCheck.long(v_, path + "/count", count, minimum = 1L, maximum = 100000L)
        ContractCheck.nested(v_, path + "/ha_group", haGroup)
        ContractCheck.string(v_, path + "/rules_hash", rulesHash, rule = ContractCheck.StringRule(pattern = ContractPatterns.P15))
        ContractCheck.nested(v_, path + "/reliability", reliability)
        ContractCheck.string(v_, path + "/version", version, rule = ContractCheck.StringRule(maxLength = 32))
        val present_ = mutableSetOf<String>()
        present_.add("id")
        present_.add("type")
        present_.add("at")
        if (clientId != null) present_.add("client_id")
        if (haUserId != null) present_.add("ha_user_id")
        if (entityId != null) present_.add("entity_id")
        if (action != null) present_.add("action")
        if (route != null) present_.add("route")
        if (origin != null) present_.add("origin")
        if (reason != null) present_.add("reason")
        if (count != null) present_.add("count")
        if (since != null) present_.add("since")
        if (haGroup != null) present_.add("ha_group")
        if (rulesHash != null) present_.add("rules_hash")
        if (reliability != null) present_.add("reliability")
        if (version != null) present_.add("version")
        val c0_ = type.value in listOf("control", "denied")
        val c1_ = type.value in listOf("denied")
        val c2_ = type.value in listOf("access_group_restored", "direct_access_attempt", "rules_applied")
        val c3_ = type.value in listOf("integration_outage")
        ContractCheck.obj(v_, path, present_, conditionals = listOf(ContractCheck.Conditional(c0_, listOf("client_id", "entity_id", "action", "route"), listOf(), listOf(), listOf()), ContractCheck.Conditional(c1_, listOf("reason"), listOf(), listOf(), listOf()), ContractCheck.Conditional(c2_, listOf("client_id"), listOf(), listOf(), listOf()), ContractCheck.Conditional(c3_, listOf("since"), listOf(), listOf(), listOf())))
        return v_
    }
}

@Serializable
