/**
 * The integration delivers the long-lived access token of a device's own HA user. Integration
 * token only. Idempotent: the same refresh_token_id again is acknowledged with unchanged=true and
 * nothing is re-sent to the app; a different refresh_token_id replaces the stored token (rotation)
 * and the hub pushes client_config_updated to the device, waits for its get_client_config (max 5
 * s) plus 3 s, then answers. The integration removes every other token of that HA user only AFTER
 * the 200. The bearer is stored encrypted, never logged, never returned. Binding: the hub accepts
 * a delivery only (a) while the device waits for its token (ha_token_status pending, listed in
 * provisioning[]), (b) with the request_id of an open rotation of this device, or (c) unsolicited
 * for the HA user already stored for the device (the integration rotates on its own when
 * local_only changes or a guest token no longer covers the expiry). Anything else is answered 422
 * request_required. Under the Supervisor the integration token itself is accepted only from the
 * hub's own host (Home Assistant Core), never from the LAN or other add-ons.
 * Schema: `schemas/integration/client-token.request.json`.
 */
@Serializable
data class IntegrationClientTokenRequest(
    @SerialName("client_id") val clientId: String,
    @SerialName("ha_user_id") val haUserId: String,
    @SerialName("refresh_token_id") val refreshTokenId: String,
    /**
     * HA access token (JWT) of the device's long-lived refresh token.
     */
    @SerialName("token") val token: String,
    /**
     * Echo of provision_client.request_id / provisioning[].request_id, if the delivery answers a
     * request. Required to deliver a token for a different HA user than the stored one outside the
     * pending phase.
     */
    @SerialName("request_id") val requestId: String? = null,
) : ContractValue {
    /** Without the values of sensitive fields (x-sensitive). */
    override fun toString(): String = "IntegrationClientTokenRequest(" + listOf("clientId=" + clientId, "haUserId=" + haUserId, "refreshTokenId=" + refreshTokenId, "token=<redacted>", "requestId=" + requestId).joinToString(", ") + ")"

    override fun validate(path: String): List<ContractViolation> {
        val v_ = mutableListOf<ContractViolation>()
        ContractCheck.string(v_, path + "/client_id", clientId, rule = ContractCheck.StringRule(pattern = ContractPatterns.P1))
        ContractCheck.string(v_, path + "/ha_user_id", haUserId, rule = ContractCheck.StringRule(minLength = 1, maxLength = 128))
        ContractCheck.string(v_, path + "/refresh_token_id", refreshTokenId, rule = ContractCheck.StringRule(minLength = 1, maxLength = 128))
        ContractCheck.string(v_, path + "/token", token, rule = ContractCheck.StringRule(minLength = 1, maxLength = 4096))
        ContractCheck.string(v_, path + "/request_id", requestId, rule = ContractCheck.StringRule(pattern = ContractPatterns.P1))
        return v_
    }
}

/**
 * Schema: `schemas/integration/client-token.response.json`.
 */
@Serializable
data class IntegrationClientTokenResponse(
    @SerialName("success") val success: StrictBoolean,
    @SerialName("client_id") val clientId: String,
    @SerialName("ha_token_status") val haTokenStatus: String,
    /**
     * true when refresh_token_id equals the stored one (repeat delivery); nothing was sent to the
     * device.
     */
    @SerialName("unchanged") val unchanged: StrictBoolean,
    /**
     * A live connection of the device received client_config_updated (and fetched its config, or the 5
     * s wait expired). false = device offline; it gets the token on its next connect.
     */
    @SerialName("delivered") val delivered: StrictBoolean,
) : ContractValue {
    override fun validate(path: String): List<ContractViolation> {
        val v_ = mutableListOf<ContractViolation>()
        ContractCheck.bool(v_, path + "/success", success, const = true)
        ContractCheck.string(v_, path + "/client_id", clientId, rule = ContractCheck.StringRule(pattern = ContractPatterns.P1))
        ContractCheck.string(v_, path + "/ha_token_status", haTokenStatus, const = "active")
        return v_
    }
}

/**
 * Unauthenticated, 1 request/s per IP. Either the neutral body {v:1, status:'unknown', ts:<now>}
 * (unknown client, unsigned status, toggle off) or a signed restricting status relayed verbatim
 * from the hub. 'compliant' is never exposed (indistinguishable from unknown by design). The
 * iPhone and iPad app verifies sig (fixtures/crypto/compliance-vectors), not the age of ts; the
 * Android apps do not poll this view.
 * Schema: `schemas/integration/compliance-view.response.json`.
 */
@Serializable
data class IntegrationComplianceViewResponse(
    @SerialName("v") val v: StrictLong,
    @SerialName("status") val status: IntegrationComplianceViewResponseStatus,
    @SerialName("ts") val ts: StrictLong,
    @SerialName("sig") val sig: String? = null,
) : ContractValue {
    override fun validate(path: String): List<ContractViolation> {
        val v_ = mutableListOf<ContractViolation>()
        ContractCheck.long(v_, path + "/v", v, const = 1L)
        ContractCheck.nested(v_, path + "/status", status)
        ContractCheck.string(v_, path + "/sig", sig, rule = ContractCheck.StringRule(pattern = ContractPatterns.P15))
        val present_ = mutableSetOf<String>()
        present_.add("v")
        present_.add("status")
        present_.add("ts")
        if (sig != null) present_.add("sig")
        val c0_ = status.value in listOf("unknown")
        ContractCheck.obj(v_, path, present_, conditionals = listOf(ContractCheck.Conditional(c0_, listOf(), listOf("sig"), listOf("sig"), listOf())))
        return v_
    }
}

