    @SerialName("hub_remote_at") val hubRemoteAt: String? = null,
) : ContractValue {
    override fun validate(path: String): List<ContractViolation> {
        val v_ = mutableListOf<ContractViolation>()
        ContractCheck.string(v_, path + "/client_id", clientId, rule = ContractCheck.StringRule(pattern = ContractPatterns.P1))
        ContractCheck.string(v_, path + "/expires_at", expiresAt, rule = ContractCheck.StringRule(format = "date-time"))
        ContractCheck.bool(v_, path + "/dry_run", dryRun, const = true)
        return v_
    }
}

/**
 * Integration token only. A button of an actionable Home Assistant notification for a child's
 * request was pressed (event mobile_app_notification_action, action <NS>_FAMILY_<token>). The
 * token (16 random bytes, base64url) is single-use, bound to one request and one notify action
 * (data/family.json notify_actions) and dies with the request; the hub stores only its SHA-256.
 * ha_user_name and notify_service are recorded in the log (route ha_notification). Not a login:
 * whoever holds the notification can answer it, therefore only targets the admin linked to a
 * family manager or chose for kids_release_requested get buttons.
 * Schema: `schemas/integration/family-notify-answer.request.json`.
 */
