/**
 * Integration action that switches on behalf of a device. Allowed for every authenticated user,
 * but only device users of the integration (decided by their rule snapshot), admins and system
 * calls get anything executed; others get not_a_device. Executes as the system with the caller's
 * context as parent (the logbook names the device user). Called by apps over the HA WebSocket
 * (call_service domain <ns>, service control, service_data = this object, return_response true) or
 * REST POST /api/services/<ns>/control?return_response. A single entity that is rejected raises
 * ServiceValidationError (translation_domain <ns>, translation_key = $defs/control_denial_reason,
 * placeholders entity_id, until); a batch (entity_ids) executes what is allowed and reports per
 * entity in the answer (without return_response a partly rejected batch raises
 * control_partly_denied after executing the allowed ones). check_only evaluates without executing
 * (always with return_response; for greying out and as health check). Allowed actions and fields:
 * data/control-allowlist.json. entity_id and entity_ids are mutually exclusive (checked by
 * tools/validate.py and the integration: not_allowed_field).
 * Schema: `schemas/integration/ha-control.request.json`.
 */
@Serializable
data class IntegrationHaControlRequest(
    /**
     * One entity (raises on rejection).
     */
    @SerialName("entity_id") val entityId: String? = null,
    /**
     * Batch of one action such as “all off”: what is allowed is executed, the answer reports per
     * entity. Not together with entity_id.
     */
    @SerialName("entity_ids") val entityIds: List<String>? = null,
    /**
     * Action of the entity's own domain, e.g. turn_on (light.turn_on for light.x).
     */
    @SerialName("action") val action: String,
    /**
     * Action data without target keys; every key must be allowed for the domain and action.
     */
    @SerialName("data") val data: JsonObject? = null,
    /**
     * Missing = app.
     */
    @SerialName("origin") val origin: ControlOrigin? = null,
    /**
     * Evaluate only, execute nothing. Missing = false.
     */
    @SerialName("check_only") val checkOnly: StrictBoolean? = null,
    /**
     * Only the hub, for child devices: pre-authorization it already counted; forwarded unchanged in
     * POST /api/integration/kids-check.
     */
    @SerialName("grant") val grant: String? = null,
) : ContractValue {
    /** Without the values of sensitive fields (x-sensitive). */
    override fun toString(): String = "IntegrationHaControlRequest(" + listOf("entityId=" + entityId, "entityIds=" + entityIds, "action=" + action, "data=" + data, "origin=" + origin, "checkOnly=" + checkOnly, "grant=<redacted>").joinToString(", ") + ")"

    override fun validate(path: String): List<ContractViolation> {
        val v_ = mutableListOf<ContractViolation>()
        ContractCheck.string(v_, path + "/entity_id", entityId, rule = ContractCheck.StringRule(pattern = ContractPatterns.P3, maxLength = 255))
        ContractCheck.items(v_, path + "/entity_ids", entityIds, minItems = 1, maxItems = 50, unique = true)
        entityIds?.forEachIndexed { i0_, x0_ ->
            ContractCheck.string(v_, path + "/entity_ids" + "/" + i0_, x0_, rule = ContractCheck.StringRule(pattern = ContractPatterns.P3, maxLength = 255))
        }
        ContractCheck.string(v_, path + "/action", action, rule = ContractCheck.StringRule(pattern = ContractPatterns.P19))
        ContractCheck.map(v_, path + "/data", data, maxProperties = 20)
        ContractCheck.nested(v_, path + "/origin", origin)
        ContractCheck.string(v_, path + "/grant", grant, rule = ContractCheck.StringRule(minLength = 16, maxLength = 128))
        val present_ = mutableSetOf<String>()
        if (entityId != null) present_.add("entity_id")
        if (entityIds != null) present_.add("entity_ids")
        present_.add("action")
        if (data != null) present_.add("data")
        if (origin != null) present_.add("origin")
        if (checkOnly != null) present_.add("check_only")
        if (grant != null) present_.add("grant")
        ContractCheck.obj(v_, path, present_, anyOfRequired = listOf(listOf("entity_id"), listOf("entity_ids")))
        return v_
    }
}

@Serializable
data class IntegrationHaControlResponseResultsItem(
    @SerialName("entity_id") val entityId: String,
    /**
     * Allowed (and executed without error unless check_only).
     */
    @SerialName("ok") val ok: StrictBoolean,
    @SerialName("executed") val executed: StrictBoolean,
    @SerialName("reason") val reason: ControlDenialReason?,
    /**
     * Kids bedtime or pause: when it ends.
     */
    @SerialName("until") val until: String? = null,
    /**
     * Values the integration changed before executing (kids volume cap: {"volume_level": 0.4}).
     */
    @SerialName("adjusted") val adjusted: JsonObject? = null,
) : ContractValue {
    override fun validate(path: String): List<ContractViolation> {
        val v_ = mutableListOf<ContractViolation>()
        ContractCheck.string(v_, path + "/entity_id", entityId, rule = ContractCheck.StringRule(pattern = ContractPatterns.P3, maxLength = 255))
        ContractCheck.nested(v_, path + "/reason", reason)
        return v_
    }
}

/**
 * Response of <ns>.control (return_response true): one result per requested entity in request
 * order.
 * Schema: `schemas/integration/ha-control.response.json`.
 */
@Serializable
data class IntegrationHaControlResponse(
    @SerialName("route") val route: ControlRoute,
    /**
     * Snapshot used (null for admins and system calls). Apps compare it with
     * client_config.ha_enforcement.rules_hash (drift).
     */
    @SerialName("rules_hash") val rulesHash: String?,
    @SerialName("results") val results: List<IntegrationHaControlResponseResultsItem>,
) : ContractValue {
    override fun validate(path: String): List<ContractViolation> {
        val v_ = mutableListOf<ContractViolation>()
        ContractCheck.nested(v_, path + "/route", route)
        ContractCheck.string(v_, path + "/rules_hash", rulesHash, rule = ContractCheck.StringRule(pattern = ContractPatterns.P15))
        ContractCheck.items(v_, path + "/results", results, minItems = 1, maxItems = 50)
        ContractCheck.nested(v_, path + "/results", results)
        return v_
    }
}

/**
 * Fired on the HA event bus for every event of the taxonomy (data/events.json), immediately and
 * without thresholds, so owners can build their own automations (no automation engine in <brand>;
 * notifications with targets, filters, quiet hours and bundling belong to the hub,
 * rest/event-notifications.json). Kinds with source integration are fired by the integration
 * itself, kinds with source hub when the hub sends ws/integration/ha_event; a test (test true) of
 * any kind also comes from the hub. Data minimization: only these fields, never action data,
 * codes, IP addresses or tokens. Only admins can subscribe to it over the WebSocket API.
 * Schema: `schemas/integration/ha-event.event.json`.
 */
@Serializable
data class IntegrationHaEventEvent(
    @SerialName("kind") val kind: EventKind,
    @SerialName("category") val category: EventCategory,
    @SerialName("at") val at: String,
    @SerialName("client_id") val clientId: String? = null,
    /**
     * Display name of the device (without brand prefix).
     */
    @SerialName("device_name") val deviceName: String? = null,
    /**
     * Person the device belongs to.
     */
    @SerialName("owner_label") val ownerLabel: String? = null,
    @SerialName("profile_id") val profileId: String? = null,
    @SerialName("entity_id") val entityId: String? = null,
    @SerialName("action") val action: String? = null,
    @SerialName("route") val route: ControlRoute? = null,
    @SerialName("reason") val reason: ControlDenialReason? = null,
    /**
     * access_opened/access_closed: why access changed (schedule = access hours, switch = access
     * switch).
     */
    @SerialName("access_reason") val accessReason: AccessClosedReason? = null,
    @SerialName("count") val count: StrictLong? = null,
    @SerialName("since") val since: String? = null,
    /**
     * Bedtime/pause end, adjustment or guest expiry; access_opened: end of the access window (null =
     * no end); access_closed: next opening (null = unknown).
     */
    @SerialName("until") val until: String? = null,
    /**
     * tag_scanned only.
     */
    @SerialName("tag_id") val tagId: String? = null,
    /**
     * tag_scanned only: name of the tag in the hub.
     */
    @SerialName("tag_name") val tagName: String? = null,
    /**
     * tag_scanned only.
     */
    @SerialName("result") val result: TagScanResult? = null,
    /**
     * true for “Send test” of a notification rule (POST /api/settings/event-notifications/test): the
     * hub sends it for any kind, also kinds with source integration, and the integration fires it
     * unchanged with test true so automations can be tried out (and filter it). Absent for real
     * events.
     */
    @SerialName("test") val test: StrictBoolean? = null,
) : ContractValue {
    override fun validate(path: String): List<ContractViolation> {
        val v_ = mutableListOf<ContractViolation>()
        ContractCheck.nested(v_, path + "/kind", kind)
        ContractCheck.nested(v_, path + "/category", category)
        ContractCheck.string(v_, path + "/client_id", clientId, rule = ContractCheck.StringRule(pattern = ContractPatterns.P1))
        ContractCheck.string(v_, path + "/device_name", deviceName, rule = ContractCheck.StringRule(maxLength = 100))
        ContractCheck.string(v_, path + "/owner_label", ownerLabel, rule = ContractCheck.StringRule(maxLength = 50))
        ContractCheck.string(v_, path + "/profile_id", profileId, rule = ContractCheck.StringRule(pattern = ContractPatterns.P1))
        ContractCheck.string(v_, path + "/entity_id", entityId, rule = ContractCheck.StringRule(pattern = ContractPatterns.P3, maxLength = 255))
        ContractCheck.string(v_, path + "/action", action, rule = ContractCheck.StringRule(pattern = ContractPatterns.P19))
        ContractCheck.nested(v_, path + "/route", route)
        ContractCheck.nested(v_, path + "/reason", reason)
        ContractCheck.nested(v_, path + "/access_reason", accessReason)
        ContractCheck.long(v_, path + "/count", count, minimum = 1L)
        ContractCheck.string(v_, path + "/tag_id", tagId, rule = ContractCheck.StringRule(pattern = ContractPatterns.P35))
        ContractCheck.string(v_, path + "/tag_name", tagName, rule = ContractCheck.StringRule(maxLength = 60))
        ContractCheck.nested(v_, path + "/result", result)
        return v_
    }
}

/**
 * Hub -> integration push session only. An event of the taxonomy with source hub (pairing, guests,
 * profiles, adjustments, kids release request); the integration fires it as <ns>_event (and as
 * <ns>_alarm for alarm kinds) unchanged. Other kinds are ignored (the integration fires those
 * itself), except a test (data.test true, “Send test” of a notification rule), which the
 * integration fires for any kind of the taxonomy with test true. Fire-and-forget, nothing is
 * queued while the integration session is down.
 * Schema: `schemas/ws/integration/ha_event.json`.
 */
@Serializable
data class IntegrationHaEvent(
    @EncodeDefault @SerialName("type") val type: String = TYPE,
    @SerialName("data") val data: IntegrationHaEventEvent,
) : ContractValue, ServerMessage {
    companion object {
        const val TYPE: String = "ha_event"
    }

    override fun validate(path: String): List<ContractViolation> {
        val v_ = mutableListOf<ContractViolation>()
        ContractCheck.string(v_, path + "/type", type, const = TYPE)
        ContractCheck.nested(v_, path + "/data", data)
        return v_
    }
}

/**
 * Integration action for the position of a device with a Home Assistant key (docs/location.md):
 * works at home and away (Nabu Casa, external URL), also for read-only device users (control path
 * checked). Allowed for every authenticated user; only device users of the integration with a rule
 * snapshot get anything done (others: not_a_device, rules_missing). The integration checks the
 * rule location of the snapshot (off → location_not_allowed, background fix with foreground →
 * location_background_not_allowed), the age of ts (location_stale) and one report per 5 s per
 * device (rate_limited), updates the device's device_tracker and sends the hub only metadata (POST
 * /api/integration/location-status, never coordinates). Refusals raise ServiceValidationError
 * (translation_domain <ns>, translation_key = $defs/location_report_reason). Called by apps over
 * the HA WebSocket (call_service domain <ns>, service report_location, service_data = this object,
 * return_response true) or REST POST /api/services/<ns>/report_location?return_response. Apps
 * never call device_tracker.see.
 * Schema: `schemas/integration/ha-report-location.request.json`.
 */
@Serializable
data class IntegrationHaReportLocationRequest(
    @SerialName("latitude") val latitude: StrictDouble,
    @SerialName("longitude") val longitude: StrictDouble,
    /**
     * Horizontal accuracy in m.
     */
    @SerialName("accuracy") val accuracy: StrictDouble,
    @SerialName("altitude") val altitude: StrictDouble? = null,
    @SerialName("vertical_accuracy") val verticalAccuracy: StrictDouble? = null,
    /**
     * m/s.
     */
    @SerialName("speed") val speed: StrictDouble? = null,
    @SerialName("course") val course: StrictDouble? = null,
    @SerialName("battery_level") val batteryLevel: StrictLong? = null,
    /**
     * Fix taken while the app was not in the foreground.
     */
    @SerialName("background") val background: StrictBoolean,
    /**
     * Time of the fix (UTC).
     */
    @SerialName("ts") val ts: String,
    /**
     * What the app shares now; forwarded to the hub (admin UI).
     */
    @SerialName("location_shared") val locationShared: LocationShared? = null,
) : ContractValue {
    override fun validate(path: String): List<ContractViolation> {
        val v_ = mutableListOf<ContractViolation>()
        ContractCheck.double(v_, path + "/latitude", latitude, minimum = -90.0, maximum = 90.0)
        ContractCheck.double(v_, path + "/longitude", longitude, minimum = -180.0, maximum = 180.0)
        ContractCheck.double(v_, path + "/accuracy", accuracy, minimum = 0.0, maximum = 100000.0)
        ContractCheck.double(v_, path + "/altitude", altitude, minimum = -1000.0, maximum = 100000.0)
        ContractCheck.double(v_, path + "/vertical_accuracy", verticalAccuracy, minimum = 0.0, maximum = 100000.0)
        ContractCheck.double(v_, path + "/speed", speed, minimum = 0.0, maximum = 1000.0)
        ContractCheck.double(v_, path + "/course", course, minimum = 0.0, maximum = 360.0)
        ContractCheck.long(v_, path + "/battery_level", batteryLevel, minimum = 0L, maximum = 100L)
        ContractCheck.string(v_, path + "/ts", ts, rule = ContractCheck.StringRule(format = "date-time"))
        ContractCheck.nested(v_, path + "/location_shared", locationShared)
        return v_
    }
}

/**
 * Response of <ns>.report_location (return_response true). applied false = the fix is older than
 * the last one of the device and was ignored. (The hub way answers applied false also when no
 * integration took the fix: ws/server/location_report_ok.json.)
 * Schema: `schemas/integration/ha-report-location.response.json`.
 */
@Serializable
data class IntegrationHaReportLocationResponse(
    @SerialName("applied") val applied: StrictBoolean,
) : ContractValue {
    override fun validate(path: String): List<ContractViolation> = emptyList()
}

/**
 * Fired by the integration when the hub reports a resolved tag (ws/integration/ha_event with kind
