) : ContractValue {
    override fun validate(path: String): List<ContractViolation> {
        val v_ = mutableListOf<ContractViolation>()
        ContractCheck.string(v_, path + "/type", type, rule = ContractCheck.StringRule(pattern = ContractPatterns.P65))
        return v_
    }
}

@Serializable
data class IntegrationHaWsFamilyResultMessagesItem(
    @SerialName("type") val type: String,
) : ContractValue {
    override fun validate(path: String): List<ContractViolation> {
