/**
 * Asks the integration to make sure the device has its own HA user with exactly one long-lived
 * access token and to deliver that token via POST /api/integration/client-token. Sent as WS push
 * provision_client and repeated in GET /api/integration/status provisioning[] until the hub has
 * the token. Handling MUST be idempotent: token_action=ensure reuses the device's existing token
 * (a new access token is derived from the same refresh token, refresh_token_id stays the same);
 * only token_action=rotate mints a new one.
 * Schema: `schemas/common/provision-request.json`.
 */
@Serializable
data class ProvisionRequest(
    @SerialName("client_id") val clientId: String,
    @SerialName("display_name") val displayName: String,
    @SerialName("owner_label") val ownerLabel: String? = null,
    @SerialName("is_guest") val isGuest: StrictBoolean,
    /**
     * Device may use HA from outside the local network: the effective profile rule remote_access.
     * Default false (local-first); also for guests when their profile allows it and for devices with
     * parental controls (read-only key, docs/enforcement.md §7).
     */
    @SerialName("remote_allowed") val remoteAllowed: StrictBoolean,
    /**
     * Guest expiry (UTC). The integration bounds the HA-side token lifetime to expiry + 7 days grace
     * and rotates the token when an extension is no longer covered.
     */
    @SerialName("guest_expires_at") val guestExpiresAt: String? = null,
    /**
     * Correlation id for logs; not used for deduplication.
     */
    @SerialName("request_id") val requestId: String? = null,
    /**
     * ensure: create user/token if missing, otherwise re-deliver the current token. rotate: mint a new
     * token for the same user; the integration removes the old one only after the hub acknowledged the
     * new one.
     */
    @SerialName("token_action") val tokenAction: ProvisionRequestTokenAction,
    /**
     * Why the hub asks (logging, UI). pair = newly paired device (status pending); retry = earlier
     * request unanswered; rotate = admin rotate-token; guest_extend = guest extended beyond the token
     * lifetime; reprovision = the hub has no usable token for an active device (e.g. restored backup).
     */
    @SerialName("reason") val reason: ProvisionRequestReason,
) : ContractValue {
    override fun validate(path: String): List<ContractViolation> {
        val v_ = mutableListOf<ContractViolation>()
        ContractCheck.string(v_, path + "/client_id", clientId, rule = ContractCheck.StringRule(pattern = ContractPatterns.P1))
        ContractCheck.string(v_, path + "/display_name", displayName, rule = ContractCheck.StringRule(minLength = 1, maxLength = 100))
        ContractCheck.string(v_, path + "/owner_label", ownerLabel, rule = ContractCheck.StringRule(maxLength = 50))
        ContractCheck.string(v_, path + "/guest_expires_at", guestExpiresAt, rule = ContractCheck.StringRule(format = "date-time"))
        ContractCheck.string(v_, path + "/request_id", requestId, rule = ContractCheck.StringRule(pattern = ContractPatterns.P1))
        ContractCheck.nested(v_, path + "/token_action", tokenAction)
        ContractCheck.nested(v_, path + "/reason", reason)
        val present_ = mutableSetOf<String>()
        present_.add("client_id")
        present_.add("display_name")
        if (ownerLabel != null) present_.add("owner_label")
        present_.add("is_guest")
        present_.add("remote_allowed")
        if (guestExpiresAt != null) present_.add("guest_expires_at")
        if (requestId != null) present_.add("request_id")
        present_.add("token_action")
        present_.add("reason")
        val c0_ = isGuest in listOf(true)
        ContractCheck.obj(v_, path, present_, conditionals = listOf(ContractCheck.Conditional(c0_, listOf("guest_expires_at", "guest_expires_at"), listOf(), listOf(), listOf())))
        return v_
    }
}

