        ContractCheck.string(v_, path + "/guest_expires_at", guestExpiresAt, rule = ContractCheck.StringRule(maxLength = 100))
        ContractCheck.items(v_, path + "/guest_tags", guestTags, maxItems = 50)
        ContractCheck.string(v_, path + "/profile", profile, rule = ContractCheck.StringRule(maxLength = 40))
