/**
 * Full snapshot for the HA integration (poll 30 s, 300 s with WS push). Contains names and GPS
 * positions. Per-device users: per-client ha_user_id/ha_token_status/owner_label/remote_allowed
 * and the provisioning[] backlog; no owner token any more. ha_user_holds: HA users kept until a
 * deleted device confirmed its reset.
 * Schema: `schemas/integration/status.response.json`.
 */
@Serializable
data class IntegrationStatusResponse(
    @SerialName("hub") val hub: IntegrationStatusResponseHub,
    @SerialName("areas") val areas: List<IntegrationStatusResponseAreasItem>,
    @SerialName("clients") val clients: List<IntegrationStatusResponseClientsItem>,
    @SerialName("guests") val guests: List<IntegrationStatusResponseGuestsItem>,
    @SerialName("guest_count") val guestCount: StrictLong,
    @SerialName("pairing_active") val pairingActive: StrictBoolean,
    @SerialName("pairing_remaining") val pairingRemaining: StrictLong,
    @SerialName("pairing_is_guest") val pairingIsGuest: StrictBoolean,
    @SerialName("pairing_guest_expires_at") val pairingGuestExpiresAt: String? = null,
    /**
     * Hub option pairing_qr_camera: when GET /api/integration/pairing-qr returns the QR code with the
     * PIN (X-Pairing-Pin: included). off = never, guests = only during a guest pairing window
     * (X-Pairing-Kind: guest), all = during every window. The integration shows an included image only
     * when this mode allows its X-Pairing-Kind. Missing = off.
     */
    @SerialName("pairing_qr_camera") val pairingQrCamera: IntegrationStatusResponsePairingQrCamera? = null,
    @SerialName("allow_pairing_via_integration") val allowPairingViaIntegration: StrictBoolean,
    @SerialName("compliance_endpoint_enabled") val complianceEndpointEnabled: StrictBoolean,
    @SerialName("tombstones") val tombstones: List<IntegrationStatusResponseTombstonesItem>,
    @SerialName("area_count") val areaCount: StrictLong,
    @SerialName("client_count") val clientCount: StrictLong,
    /**
     * Outstanding provisioning requests (same shape as provision_client.data): every active client
     * with ha_token_status=pending (reason pair/reprovision) and rotations not yet answered (reason
     * rotate/guest_extend). Fallback for a missed WS push; the integration handles each item exactly
     * like a provision_client message. Empty = nothing to do.
     */
    @SerialName("provisioning") val provisioning: List<ProvisionRequest>,
    /**
     * Deleted devices whose HA user stays until the app confirmed its reset (client_reset_ack) or the
     * grace period ran out (24 h offline); hidden tombstones included. The integration must not remove
     * the HA user of a listed client id on its own (reconcile skips it); the hub sends
     * deprovision_client when it releases the hold. Empty = no holds.
     */
    @SerialName("ha_user_holds") val haUserHolds: List<String>,
    /**
     * Rule snapshots for the integration action <ns>.control. Missing = the hub does not deliver
     * snapshots (the integration keeps the ones it has).
     */
    @SerialName("enforcement") val enforcement: IntegrationStatusResponseEnforcement? = null,
) : ContractValue {
    override fun validate(path: String): List<ContractViolation> {
        val v_ = mutableListOf<ContractViolation>()
        ContractCheck.nested(v_, path + "/hub", hub)
        ContractCheck.nested(v_, path + "/areas", areas)
        ContractCheck.nested(v_, path + "/clients", clients)
        ContractCheck.nested(v_, path + "/guests", guests)
        ContractCheck.long(v_, path + "/pairing_remaining", pairingRemaining, minimum = 0L)
        ContractCheck.nested(v_, path + "/pairing_qr_camera", pairingQrCamera)
        ContractCheck.nested(v_, path + "/tombstones", tombstones)
        ContractCheck.items(v_, path + "/provisioning", provisioning, maxItems = 500)
        ContractCheck.nested(v_, path + "/provisioning", provisioning)
        ContractCheck.items(v_, path + "/ha_user_holds", haUserHolds, maxItems = 500)
        haUserHolds.forEachIndexed { i0_, x0_ ->
            ContractCheck.string(v_, path + "/ha_user_holds" + "/" + i0_, x0_, rule = ContractCheck.StringRule(pattern = ContractPatterns.P1))
        }
        ContractCheck.nested(v_, path + "/enforcement", enforcement)
        return v_
    }
}

/**
 * Hub -> integration push session only. The device was renamed, its owner label, remote access or
 * guest expiry changed. The integration updates the HA user (name, local_only). When local_only
 * changes, or a guest expiry is no longer covered by the token lifetime, it rotates the token (new
 * token delivered via POST /api/integration/client-token, old token removed after the
 * acknowledgement; HA closes open sessions of the removed token, so the app re-authenticates under
 * the new rules). Carries the full identity (not a diff), so applying it twice is harmless. The
 * same state is also visible in GET /api/integration/status clients[], which the integration
 * reconciles on every poll.
 * Schema: `schemas/ws/integration/update_client_identity.json`.
 */
@Serializable
data class IntegrationUpdateClientIdentity(
    @EncodeDefault @SerialName("type") val type: String = TYPE,
    @SerialName("data") val data: ClientIdentity,
) : ContractValue, ServerMessage {
    companion object {
        const val TYPE: String = "update_client_identity"
    }

    override fun validate(path: String): List<ContractViolation> {
        val v_ = mutableListOf<ContractViolation>()
        ContractCheck.string(v_, path + "/type", type, const = TYPE)
        ContractCheck.nested(v_, path + "/data", data)
        return v_
    }
}

