    /**
     * show_camera only: the camera to open.
     */
    @SerialName("entity_id") val entityId: String? = null,
) : ContractValue, ServerMessage {
    companion object {
        const val TYPE: String = "command"
        const val COMMAND: String = "panel_command"
    }

    override fun validate(path: String): List<ContractViolation> {
        val v_ = mutableListOf<ContractViolation>()
        ContractCheck.string(v_, path + "/type", type, const = TYPE)
        ContractCheck.string(v_, path + "/command", command, const = COMMAND)
        ContractCheck.string(v_, path + "/id", id, rule = ContractCheck.StringRule(pattern = ContractPatterns.P1))
        ContractCheck.nested(v_, path + "/action", action)
        ContractCheck.double(v_, path + "/level", level, minimum = 0.05, maximum = 1.0)
        ContractCheck.nested(v_, path + "/mode", mode)
        ContractCheck.string(v_, path + "/text", text, rule = ContractCheck.StringRule(minLength = 1, maxLength = 300))
        ContractCheck.long(v_, path + "/volume", volume, minimum = 0L, maximum = 100L)
        ContractCheck.string(v_, path + "/entity_id", entityId, rule = ContractCheck.StringRule(pattern = ContractPatterns.P55, maxLength = 255))
        val present_ = mutableSetOf<String>()
        present_.add("id")
        present_.add("action")
        if (level != null) present_.add("level")
        if (mode != null) present_.add("mode")
        if (text != null) present_.add("text")
        if (volume != null) present_.add("volume")
        if (chime != null) present_.add("chime")
        if (entityId != null) present_.add("entity_id")
        val c0_ = action.value in listOf("set_brightness")
        val c1_ = action.value in listOf("set_brightness_mode")
        val c2_ = action.value in listOf("announce")
        val c3_ = action.value in listOf("show_camera")
        ContractCheck.obj(v_, path, present_, conditionals = listOf(ContractCheck.Conditional(c0_, listOf("level"), listOf(), listOf(), listOf()), ContractCheck.Conditional(c1_, listOf("mode"), listOf(), listOf(), listOf()), ContractCheck.Conditional(c2_, listOf("text"), listOf(), listOf(), listOf()), ContractCheck.Conditional(c3_, listOf("entity_id"), listOf(), listOf(), listOf())))
        return v_
    }
}

