/**
 * PIN for a new device. access: member (default) or guest. profile_id missing or null = default
 * profile of the device type that pairs (house settings; guest: default guest profile). Guests:
 * duration guest_hours (default guest_default_hours, max guest_access.max_hours) or
 * guest_expires_at. 422 profile.guest_child_protection for a guest with a parental-controls
 * profile.
 * Schema: `schemas/rest/pairing-generate.request.json`.
 */
@Serializable
data class RestPairingGenerateRequest(
    @SerialName("access") val access: DeviceAccess? = null,
    @SerialName("profile_id") val profileId: String? = null,
    @SerialName("own_area_id") val ownAreaId: String? = null,
    @SerialName("owner_label") val ownerLabel: String? = null,
    @SerialName("guest_hours") val guestHours: StrictLong? = null,
    /**
     * Own end of the guest access; not together with guest_hours (422 guest.expires).
     */
    @SerialName("guest_expires_at") val guestExpiresAt: String? = null,
) : ContractValue {
    override fun validate(path: String): List<ContractViolation> {
        val v_ = mutableListOf<ContractViolation>()
        ContractCheck.nested(v_, path + "/access", access)
        ContractCheck.string(v_, path + "/profile_id", profileId, rule = ContractCheck.StringRule(pattern = ContractPatterns.P1))
        ContractCheck.string(v_, path + "/own_area_id", ownAreaId, rule = ContractCheck.StringRule(pattern = ContractPatterns.P1))
        ContractCheck.string(v_, path + "/owner_label", ownerLabel, rule = ContractCheck.StringRule(maxLength = 50))
        ContractCheck.long(v_, path + "/guest_hours", guestHours, minimum = 1L, maximum = 2160L)
        val present_ = mutableSetOf<String>()
        if (access != null) present_.add("access")
        if (profileId != null) present_.add("profile_id")
        if (ownAreaId != null) present_.add("own_area_id")
        if (ownerLabel != null) present_.add("owner_label")
        if (guestHours != null) present_.add("guest_hours")
        if (guestExpiresAt != null) present_.add("guest_expires_at")
        val c0_ = access?.let { it.value in listOf("member") } ?: true
        ContractCheck.obj(v_, path, present_, conditionals = listOf(ContractCheck.Conditional(c0_, listOf(), listOf("guest_hours"), listOf(), listOf())))
        return v_
    }
}

