/**
 * Create an empty profile (POST: name required; rules missing = catalog defaults,
 * fixed/user_choice missing = catalog default_fixed/default_user_choice) or change one (PATCH:
 * every field optional; rules is merged per key, fixed and user_choice replace the whole list).
 * Validation 422 per field (rules.<key>, fixed, user_choice.<key> not allowed, name.duplicate,
 * profile.limit, profile.guest_child_protection). Making a rule fixed deletes its device
 * adjustments; a change of control_path or remote_access that takes a device's Home Assistant key
 * away rotates its HA token - see ?dry_run=true (profile-preview.response.json) before saving.
 * Schema: `schemas/rest/profile-write.request.json`.
 */
@Serializable
data class RestProfileWriteRequest(
    @SerialName("name") val name: String? = null,
    /**
     * Kind of the profile. POST without kind: person. Changing the kind changes no rule; a profile
     * that is no longer of kind person loses setup_devices (resolved not_applicable).
     */
    @SerialName("kind") val kind: ProfileKind? = null,
    /**
     * One sentence for the profile card.
     */
    @SerialName("description") val description: String? = null,
    @SerialName("icon") val icon: String? = null,
    @SerialName("color") val color: String? = null,
    @SerialName("child_protection") val childProtection: StrictBoolean? = null,
    @SerialName("rules") val rules: ProfileRuleValues? = null,
    @SerialName("fixed") val fixed: List<ProfileRuleKey>? = null,
    @SerialName("user_choice") val userChoice: List<ProfileRuleKey>? = null,
    /**
     * Profile remote PIN: exactly 8 digits, stored only as PBKDF2 hash + salt
     * (fixtures/crypto/settings-pin-vectors); null removes it. Never in log, audit, diff or preview
     * (the audit only notes profile_remote_pin_set).
     */
    @SerialName("remote_pin") val remotePin: String? = null,
    @SerialName("remote_pin_fixed") val remotePinFixed: StrictBoolean? = null,
) : ContractValue {
    /** Without the values of sensitive fields (x-sensitive). */
    override fun toString(): String = "RestProfileWriteRequest(" + listOf("name=" + name, "kind=" + kind, "description=" + description, "icon=" + icon, "color=" + color, "childProtection=" + childProtection, "rules=" + rules, "fixed=" + fixed, "userChoice=" + userChoice, "remotePin=<redacted>", "remotePinFixed=" + remotePinFixed).joinToString(", ") + ")"

    override fun validate(path: String): List<ContractViolation> {
        val v_ = mutableListOf<ContractViolation>()
        ContractCheck.string(v_, path + "/name", name, rule = ContractCheck.StringRule(pattern = ContractPatterns.P26, minLength = 1, maxLength = 40))
        ContractCheck.nested(v_, path + "/kind", kind)
        ContractCheck.string(v_, path + "/description", description, rule = ContractCheck.StringRule(maxLength = 300))
        ContractCheck.string(v_, path + "/icon", icon, rule = ContractCheck.StringRule(pattern = ContractPatterns.P43))
        ContractCheck.string(v_, path + "/color", color, rule = ContractCheck.StringRule(pattern = ContractPatterns.P74))
        ContractCheck.nested(v_, path + "/rules", rules)
        ContractCheck.items(v_, path + "/fixed", fixed, unique = true)
        ContractCheck.nested(v_, path + "/fixed", fixed)
        ContractCheck.items(v_, path + "/user_choice", userChoice, unique = true)
        ContractCheck.nested(v_, path + "/user_choice", userChoice)
        ContractCheck.string(v_, path + "/remote_pin", remotePin, rule = ContractCheck.StringRule(pattern = ContractPatterns.P71))
        return v_
    }
}

