/**
 * Admin only. The rotation is stored first and survives a hub restart. 200: the integration
 * delivered the new token within the wait time (ha_token_status, ha_token_minted_at; the app was
 * told via client_config_updated). 202 status rotation_requested: sent to the integration, no
 * answer yet. 202 status pending: the integration is not connected; the rotation runs as soon as
 * it is (provisioning[] on its next poll, retry loop once its push session is up), answered at
 * once. 202 status pending also for a device with remote access (remote_allowed) that is not
 * connected to the hub (away): the rotation is deferred until the device connects to the hub (it
 * is home and fetches the new token at once), at the latest after 72 h; then it runs anyway (audit
 * log, no endless deferral). There is no separate status value for this; the admin UI tells the
 * case apart by remote_allowed and is_connected of the device. 404 unknown device, 409 device not
 * active or without an HA token. There is no 503.
 * Schema: `schemas/rest/rotate-token.response.json`.
 */
@Serializable
data class RestRotateTokenResponse(
    @SerialName("ok") val ok: StrictBoolean,
    @SerialName("client_id") val clientId: String,
    @SerialName("ha_token_status") val haTokenStatus: HaTokenStatus? = null,
    @SerialName("ha_token_minted_at") val haTokenMintedAt: String? = null,
    /**
     * 202: rotation_requested (sent, waiting for the integration) or pending (integration not
     * connected, or a device with remote access that is away: deferred until it connects, max. 72 h).
     * 200: null.
     */
    @SerialName("status") val status: RestRotateTokenResponseStatus? = null,
) : ContractValue {
    override fun validate(path: String): List<ContractViolation> {
        val v_ = mutableListOf<ContractViolation>()
        ContractCheck.bool(v_, path + "/ok", ok, const = true)
        ContractCheck.string(v_, path + "/client_id", clientId, rule = ContractCheck.StringRule(pattern = ContractPatterns.P1))
        ContractCheck.nested(v_, path + "/ha_token_status", haTokenStatus)
        ContractCheck.nested(v_, path + "/status", status)
        return v_
    }
}

/**
 * Assignment of a tag in the hub.
 */
@Serializable
data class TagAction(
    @SerialName("kind") val kind: TagActionKind,
    /**
     * Target entity; required except for show with area_id.
     */
    @SerialName("entity_id") val entityId: String? = null,
    /**
     * show only: hub area to open instead of an entity.
     */
    @SerialName("area_id") val areaId: String? = null,
) : ContractValue {
    override fun validate(path: String): List<ContractViolation> {
        val v_ = mutableListOf<ContractViolation>()
        ContractCheck.nested(v_, path + "/kind", kind)
        ContractCheck.string(v_, path + "/entity_id", entityId, rule = ContractCheck.StringRule(pattern = ContractPatterns.P3, maxLength = 255))
        ContractCheck.string(v_, path + "/area_id", areaId, rule = ContractCheck.StringRule(pattern = ContractPatterns.P1))
        val present_ = mutableSetOf<String>()
        present_.add("kind")
        if (entityId != null) present_.add("entity_id")
        if (areaId != null) present_.add("area_id")
        val c0_ = kind.value in listOf("toggle", "turn_on", "turn_off", "run")
        ContractCheck.obj(v_, path, present_, conditionals = listOf(ContractCheck.Conditional(c0_, listOf("entity_id", "entity_id"), listOf(), listOf(), listOf())))
        return v_
    }
}

/**
