        val v_ = mutableListOf<ContractViolation>()
        ContractCheck.string(v_, path + "/type", type, const = TYPE)
        ContractCheck.nested(v_, path + "/reason", reason)
        ContractCheck.string(v_, path + "/message", message, rule = ContractCheck.StringRule(maxLength = 500))
        ContractCheck.nested(v_, path + "/request", request)
        ContractCheck.long(v_, path + "/retry_after", retryAfter, minimum = 0L)
        return v_
    }
}

