/**
 * Authentication failed. The socket stays open (the client may retry within the per-connection
 * limit). `reason` is machine-readable; `message` is English text for logs only.
 * Schema: `schemas/ws/server/auth_error.json`.
 */
@Serializable
data class ServerAuthError(
    @EncodeDefault @SerialName("type") val type: String = TYPE,
    @SerialName("reason") val reason: AuthErrorReason,
    /**
     * Human-readable English text for logs; not for display, not stable.
     */
    @SerialName("message") val message: String,
) : ContractValue, ServerMessage {
    companion object {
        const val TYPE: String = "auth_error"
    }

    override fun validate(path: String): List<ContractViolation> {
        val v_ = mutableListOf<ContractViolation>()
        ContractCheck.string(v_, path + "/type", type, const = TYPE)
        ContractCheck.nested(v_, path + "/reason", reason)
        ContractCheck.string(v_, path + "/message", message, rule = ContractCheck.StringRule(maxLength = 500))
        return v_
    }
}

/**
 * Authentication succeeded. Sent immediately for ingress/integration sessions, after 'auth' for
 * paired clients. A repeated 'auth' on an authenticated session yields {type: auth_ok, message:
 * 'Already authenticated'} without client_id. Always carries protocol_version,
 * min_protocol_version and min_app_version.
 * Schema: `schemas/ws/server/auth_ok.json`.
 */
@Serializable
data class ServerAuthOk(
    @EncodeDefault @SerialName("type") val type: String = TYPE,
    @SerialName("client_id") val clientId: String? = null,
    @SerialName("is_guest") val isGuest: StrictBoolean? = null,
    @SerialName("expires_at") val expiresAt: String? = null,
    @SerialName("message") val message: String? = null,
    /**
     * Protocol version of the hub. An app that cannot speak it (hub too old for the app) shows 'update
     * the hub'.
     */
    @SerialName("protocol_version") val protocolVersion: StrictLong,
    /**
     * Lowest client protocol version the hub serves.
     */
    @SerialName("min_protocol_version") val minProtocolVersion: StrictLong,
    @SerialName("min_app_version") val minAppVersion: MinAppVersion,
) : ContractValue, ServerMessage {
    companion object {
        const val TYPE: String = "auth_ok"
    }

    override fun validate(path: String): List<ContractViolation> {
        val v_ = mutableListOf<ContractViolation>()
        ContractCheck.string(v_, path + "/type", type, const = TYPE)
        ContractCheck.string(v_, path + "/client_id", clientId, alternatives = listOf(ContractCheck.StringRule(pattern = ContractPatterns.P1), ContractCheck.StringRule(oneOf = listOf("ingress", "integration", "dev", "admin"))))
        ContractCheck.bool(v_, path + "/is_guest", isGuest, const = true)
        ContractCheck.long(v_, path + "/protocol_version", protocolVersion, minimum = 1L)
        ContractCheck.long(v_, path + "/min_protocol_version", minProtocolVersion, minimum = 1L)
        ContractCheck.nested(v_, path + "/min_app_version", minAppVersion)
        val present_ = mutableSetOf<String>()
        if (clientId != null) present_.add("client_id")
        if (isGuest != null) present_.add("is_guest")
        if (expiresAt != null) present_.add("expires_at")
        if (message != null) present_.add("message")
        present_.add("protocol_version")
        present_.add("min_protocol_version")
        present_.add("min_app_version")
        ContractCheck.obj(v_, path, present_, dependentRequired = mapOf("is_guest" to listOf("expires_at")), anyOfRequired = listOf(listOf("client_id"), listOf("message")))
        return v_
    }
}

