/**
 * Answer to camera_image_get: the still image of the camera as Home Assistant delivered it, base64
 * encoded (RFC 4648, with padding, no line breaks). At most 2 MiB (2097152 bytes) of image data,
 * so data_b64 has at most 2796204 characters; a larger image or another type is answered with
 * control_error {ha_error}. content_type is one of the raster types listed; the app decodes the
 * image, it never runs it. The whole message is at most 2 800 000 bytes (x-limits
 * hub_image_message_max_bytes): clients accept WebSocket messages of that size.
 * Schema: `schemas/ws/server/camera_image.json`.
 */
@Serializable
data class ServerCameraImage(
    @EncodeDefault @SerialName("type") val type: String = TYPE,
    @SerialName("request_id") val requestId: String,
    @SerialName("entity_id") val entityId: String,
    @SerialName("content_type") val contentType: ServerCameraImageContentType,
    @SerialName("data_b64") val dataB64: String,
) : ContractValue, ServerMessage {
    companion object {
        const val TYPE: String = "camera_image"
    }

    override fun validate(path: String): List<ContractViolation> {
        val v_ = mutableListOf<ContractViolation>()
        ContractCheck.string(v_, path + "/type", type, const = TYPE)
        ContractCheck.string(v_, path + "/request_id", requestId, rule = ContractCheck.StringRule(minLength = 1, maxLength = 64))
        ContractCheck.string(v_, path + "/entity_id", entityId, rule = ContractCheck.StringRule(pattern = ContractPatterns.P55, maxLength = 255))
        ContractCheck.nested(v_, path + "/content_type", contentType)
        ContractCheck.string(v_, path + "/data_b64", dataB64, rule = ContractCheck.StringRule(pattern = ContractPatterns.P76, minLength = 4, maxLength = 2796204))
        return v_
    }
}

