 * (datetime, condition, temperature, templow, precipitation, precipitation_probability,
 * wind_speed, is_daytime …), at most 240. Empty when the entity offers no forecast of this type.
 * Schema: `schemas/ws/server/forecast.json`.
 */
@Serializable
data class ServerForecast(
    @EncodeDefault @SerialName("type") val type: String = TYPE,
    @SerialName("request_id") val requestId: String,
    @SerialName("entity_id") val entityId: String,
    @SerialName("forecast_type") val forecastType: ServerForecastForecastType,
    @SerialName("forecast") val forecast: List<ServerForecastForecastItem>,
) : ContractValue, ServerMessage {
    companion object {
        const val TYPE: String = "forecast"
    }

    override fun validate(path: String): List<ContractViolation> {
        val v_ = mutableListOf<ContractViolation>()
        ContractCheck.string(v_, path + "/type", type, const = TYPE)
        ContractCheck.string(v_, path + "/request_id", requestId, rule = ContractCheck.StringRule(minLength = 1, maxLength = 64))
        ContractCheck.string(v_, path + "/entity_id", entityId, rule = ContractCheck.StringRule(pattern = ContractPatterns.P34, maxLength = 255))
        ContractCheck.nested(v_, path + "/forecast_type", forecastType)
        ContractCheck.items(v_, path + "/forecast", forecast, maxItems = 240)
        ContractCheck.nested(v_, path + "/forecast", forecast)
        return v_
    }
}

/**
 * Sent to the connected guest after its expiry was extended. Same type name as the ADMIN
 * broadcast, different shape (top-level expires_at, no data).
 * Schema: `schemas/ws/server/guest_extended.json`.
 */
@Serializable
data class ServerGuestExtended(
    @EncodeDefault @SerialName("type") val type: String = TYPE,
    @SerialName("expires_at") val expiresAt: String,
