        val v_ = mutableListOf<ContractViolation>()
        ContractCheck.string(v_, path + "/type", type, const = TYPE)
        ContractCheck.string(v_, path + "/expires_at", expiresAt, rule = ContractCheck.StringRule(format = "date-time"))
        return v_
    }
}

/**
 * A new guest invitation of this device. pin and deep_link are secret for 5 minutes: show them
 * only on the inviting screen (large QR code of deep_link, the PIN to type). deep_link is the
 * canonical pairing link (deep-link/pairing-link.json, with tls_port/fp when the hub has a
 * certificate); a guest scans it with the camera or types the PIN in the app. grant = what the
 * guest gets (admin defaults, display only).
 * Schema: `schemas/ws/server/guest_invite.json`.
 */
@Serializable
data class ServerGuestInvite(
    @EncodeDefault @SerialName("type") val type: String = TYPE,
    @SerialName("invite_id") val inviteId: String,
    @SerialName("pin") val pin: String,
    /**
     * Canonical pairing deep link with the PIN (deep-link/pairing-link.json uri).
     */
    @SerialName("deep_link") val deepLink: String,
    /**
     * Base URL of the hub encoded in deep_link (for manual entry).
     */
    @SerialName("url") val url: String,
    @SerialName("expires_in") val expiresIn: StrictLong,
    @SerialName("expires_at") val expiresAt: String,
    @SerialName("grant") val grant: GuestInviteGrant,
) : ContractValue, ServerMessage {
    companion object {
        const val TYPE: String = "guest_invite"
    }

    /** Without the values of sensitive fields (x-sensitive). */
    override fun toString(): String = "ServerGuestInvite(" + listOf("type=" + type, "inviteId=" + inviteId, "pin=<redacted>", "deepLink=<redacted>", "url=" + url, "expiresIn=" + expiresIn, "expiresAt=" + expiresAt, "grant=" + grant).joinToString(", ") + ")"

    override fun validate(path: String): List<ContractViolation> {
        val v_ = mutableListOf<ContractViolation>()
        ContractCheck.string(v_, path + "/type", type, const = TYPE)
        ContractCheck.string(v_, path + "/invite_id", inviteId, rule = ContractCheck.StringRule(pattern = ContractPatterns.P1))
        ContractCheck.string(v_, path + "/pin", pin, rule = ContractCheck.StringRule(pattern = ContractPatterns.P38))
        ContractCheck.string(v_, path + "/deep_link", deepLink, rule = ContractCheck.StringRule(maxLength = 512))
        ContractCheck.string(v_, path + "/url", url, rule = ContractCheck.StringRule(pattern = ContractPatterns.P57))
        ContractCheck.long(v_, path + "/expires_in", expiresIn, minimum = 1L, maximum = 300L)
        ContractCheck.nested(v_, path + "/grant", grant)
        return v_
    }
}

/**
 * An invitation of this device ended (sent to every connection of the inviting device, also as the
 * answer to guest_invite_cancel). result paired carries the new guest's client_id and client_name
 * (show "Guest connected").
 * Schema: `schemas/ws/server/guest_invite_ended.json`.
 */
@Serializable
data class ServerGuestInviteEnded(
    @EncodeDefault @SerialName("type") val type: String = TYPE,
    @SerialName("invite_id") val inviteId: String,
    @SerialName("result") val result: GuestInviteResult,
    @SerialName("client_id") val clientId: String? = null,
    @SerialName("client_name") val clientName: String? = null,
) : ContractValue, ServerMessage {
    companion object {
        const val TYPE: String = "guest_invite_ended"
    }

    override fun validate(path: String): List<ContractViolation> {
        val v_ = mutableListOf<ContractViolation>()
        ContractCheck.string(v_, path + "/type", type, const = TYPE)
        ContractCheck.string(v_, path + "/invite_id", inviteId, rule = ContractCheck.StringRule(pattern = ContractPatterns.P1))
        ContractCheck.nested(v_, path + "/result", result)
        ContractCheck.string(v_, path + "/client_id", clientId, rule = ContractCheck.StringRule(pattern = ContractPatterns.P1))
        ContractCheck.string(v_, path + "/client_name", clientName, rule = ContractCheck.StringRule(maxLength = 100))
        val present_ = mutableSetOf<String>()
        present_.add("invite_id")
        present_.add("result")
        if (clientId != null) present_.add("client_id")
        if (clientName != null) present_.add("client_name")
        val c0_ = result.value in listOf("paired")
        ContractCheck.obj(v_, path, present_, conditionals = listOf(ContractCheck.Conditional(c0_, listOf("client_id", "client_name"), listOf(), listOf(), listOf())))
        return v_
    }
}

