/**
 * Answer to history_get. states oldest first: the state at the start of the period, then every
 * significant change (Home Assistant recorder, minimal response, no attributes). At most 1000
 * points; with more the hub keeps evenly spaced points including the first and the last and sets
 * truncated. unavailable/unknown are kept (the app skips them).
 * Schema: `schemas/ws/server/history.json`.
 */
@Serializable
data class ServerHistory(
    @EncodeDefault @SerialName("type") val type: String = TYPE,
    @SerialName("request_id") val requestId: String,
    @SerialName("entity_id") val entityId: String,
    @SerialName("hours") val hours: StrictLong,
    @SerialName("states") val states: List<ServerHistoryStatesItem>,
    @SerialName("truncated") val truncated: StrictBoolean,
) : ContractValue, ServerMessage {
    companion object {
        const val TYPE: String = "history"
    }

    override fun validate(path: String): List<ContractViolation> {
        val v_ = mutableListOf<ContractViolation>()
        ContractCheck.string(v_, path + "/type", type, const = TYPE)
        ContractCheck.string(v_, path + "/request_id", requestId, rule = ContractCheck.StringRule(minLength = 1, maxLength = 64))
        ContractCheck.string(v_, path + "/entity_id", entityId, rule = ContractCheck.StringRule(pattern = ContractPatterns.P3, maxLength = 255))
        ContractCheck.long(v_, path + "/hours", hours, minimum = 1L, maximum = 168L)
        ContractCheck.items(v_, path + "/states", states, maxItems = 1000)
        ContractCheck.nested(v_, path + "/states", states)
        return v_
    }
}

