/**
 * Report accepted (the rule allows it). applied true = the hub handed the fix to the integration.
 * applied false = nothing changed in Home Assistant: the fix is older than the last applied one,
 * or no integration took it (not connected); the app may send a newer fix later, and the same fix
 * counts as new again once an integration is connected. Same body as the 200 answer of POST
 * /api/client/location.
 * Schema: `schemas/ws/server/location_report_ok.json`.
 */
@Serializable
data class ServerLocationReportOk(
    @EncodeDefault @SerialName("type") val type: String = TYPE,
    /**
     * true = handed to the integration; false = older than the last applied fix, or no integration
     * took it.
     */
    @SerialName("applied") val applied: StrictBoolean,
) : ContractValue, ServerMessage {
    companion object {
        const val TYPE: String = "location_report_ok"
    }

    override fun validate(path: String): List<ContractViolation> {
        val v_ = mutableListOf<ContractViolation>()
        ContractCheck.string(v_, path + "/type", type, const = TYPE)
        return v_
    }
}

/**
 * Answer to media_image_get: the artwork of the media player as Home Assistant delivered it,
 * base64 encoded (RFC 4648, with padding, no line breaks). At most 2 MiB (2097152 bytes) of image
 * data, so data_b64 has at most 2796204 characters; a larger image or another type is answered
 * with control_error {ha_error}. content_type is one of the raster types listed; the app decodes
 * the image, it never runs it. The whole message is at most 2 800 000 bytes (x-limits
 * hub_image_message_max_bytes): clients accept WebSocket messages of that size.
 * Schema: `schemas/ws/server/media_image.json`.
 */
@Serializable
data class ServerMediaImage(
    @EncodeDefault @SerialName("type") val type: String = TYPE,
    @SerialName("request_id") val requestId: String,
    @SerialName("entity_id") val entityId: String,
    @SerialName("content_type") val contentType: ServerMediaImageContentType,
    @SerialName("data_b64") val dataB64: String,
) : ContractValue, ServerMessage {
    companion object {
        const val TYPE: String = "media_image"
    }

    override fun validate(path: String): List<ContractViolation> {
        val v_ = mutableListOf<ContractViolation>()
        ContractCheck.string(v_, path + "/type", type, const = TYPE)
        ContractCheck.string(v_, path + "/request_id", requestId, rule = ContractCheck.StringRule(minLength = 1, maxLength = 64))
        ContractCheck.string(v_, path + "/entity_id", entityId, rule = ContractCheck.StringRule(pattern = ContractPatterns.P77, maxLength = 255))
        ContractCheck.nested(v_, path + "/content_type", contentType)
        ContractCheck.string(v_, path + "/data_b64", dataB64, rule = ContractCheck.StringRule(pattern = ContractPatterns.P76, minLength = 4, maxLength = 2796204))
        return v_
    }
}

