/**
 * Pairing succeeded; the connection is authenticated. The secret is shown exactly once. Carries
 * protocol_version, min_protocol_version and min_app_version like auth_ok.
 * Schema: `schemas/ws/server/pair_ok.json`.
 */
@Serializable
data class ServerPairOk(
    @EncodeDefault @SerialName("type") val type: String = TYPE,
    @SerialName("client_id") val clientId: String,
    @SerialName("client_name") val clientName: String,
    @SerialName("secret") val secret: String,
    @SerialName("is_guest") val isGuest: StrictBoolean? = null,
    @SerialName("expires_at") val expiresAt: String? = null,
    /**
     * Protocol version of the hub. An app that cannot speak it (hub too old for the app) shows 'update
     * the hub'.
     */
    @SerialName("protocol_version") val protocolVersion: StrictLong,
    /**
     * Lowest client protocol version the hub serves.
     */
    @SerialName("min_protocol_version") val minProtocolVersion: StrictLong,
    @SerialName("min_app_version") val minAppVersion: MinAppVersion,
) : ContractValue, ServerMessage {
    companion object {
        const val TYPE: String = "pair_ok"
    }

    /** Without the values of sensitive fields (x-sensitive). */
    override fun toString(): String = "ServerPairOk(" + listOf("type=" + type, "clientId=" + clientId, "clientName=" + clientName, "secret=<redacted>", "isGuest=" + isGuest, "expiresAt=" + expiresAt, "protocolVersion=" + protocolVersion, "minProtocolVersion=" + minProtocolVersion, "minAppVersion=" + minAppVersion).joinToString(", ") + ")"

    override fun validate(path: String): List<ContractViolation> {
        val v_ = mutableListOf<ContractViolation>()
        ContractCheck.string(v_, path + "/type", type, const = TYPE)
        ContractCheck.string(v_, path + "/client_id", clientId, rule = ContractCheck.StringRule(pattern = ContractPatterns.P1))
        ContractCheck.string(v_, path + "/secret", secret, rule = ContractCheck.StringRule(pattern = ContractPatterns.P15))
        ContractCheck.bool(v_, path + "/is_guest", isGuest, const = true)
        ContractCheck.long(v_, path + "/protocol_version", protocolVersion, minimum = 1L)
        ContractCheck.long(v_, path + "/min_protocol_version", minProtocolVersion, minimum = 1L)
        ContractCheck.nested(v_, path + "/min_app_version", minAppVersion)
        val present_ = mutableSetOf<String>()
        present_.add("client_id")
        present_.add("client_name")
        present_.add("secret")
        if (isGuest != null) present_.add("is_guest")
        if (expiresAt != null) present_.add("expires_at")
        present_.add("protocol_version")
        present_.add("min_protocol_version")
        present_.add("min_app_version")
        ContractCheck.obj(v_, path, present_, dependentRequired = mapOf("is_guest" to listOf("expires_at")))
        return v_
    }
}

