 * Schema: `schemas/ws/server/subscribed.json`.
 */
@Serializable
data class ServerSubscribed(
    @EncodeDefault @SerialName("type") val type: String = TYPE,
    /**
     * area_id or 'all'
     */
    @SerialName("data") val data: String,
) : ContractValue, ServerMessage {
    companion object {
        const val TYPE: String = "subscribed"
    }

    override fun validate(path: String): List<ContractViolation> {
