    }
}

@Serializable
data class ServerTagResultTag(
    @SerialName("name") val name: String,
    @SerialName("action") val action: TagAction,
) : ContractValue {
    override fun validate(path: String): List<ContractViolation> {
        val v_ = mutableListOf<ContractViolation>()
        ContractCheck.string(v_, path + "/name", name, rule = ContractCheck.StringRule(maxLength = 60))
        ContractCheck.nested(v_, path + "/action", action)
        return v_
    }
}

/**
 * Answer to tag_resolve. tag only with result ok: name and action (show, toggle, turn_on,
 * turn_off, run). The hub checks the rule scan_tags (tags_off, also for guests) and that the
 * target is inside the device's areas (not_visible); quick access levels and the control path
 * apply when the app switches. Pro is checked by the app.
 * Schema: `schemas/ws/server/tag_result.json`.
 */
@Serializable
data class ServerTagResult(
    @EncodeDefault @SerialName("type") val type: String = TYPE,
    @SerialName("tag_id") val tagId: String,
    @SerialName("result") val result: TagScanResult,
    @SerialName("tag") val tag: ServerTagResultTag? = null,
    /**
     * rate_limited only.
     */
    @SerialName("retry_after") val retryAfter: StrictLong? = null,
) : ContractValue, ServerMessage {
    companion object {
        const val TYPE: String = "tag_result"
    }

    override fun validate(path: String): List<ContractViolation> {
        val v_ = mutableListOf<ContractViolation>()
        ContractCheck.string(v_, path + "/type", type, const = TYPE)
        ContractCheck.string(v_, path + "/tag_id", tagId, rule = ContractCheck.StringRule(pattern = ContractPatterns.P35))
        ContractCheck.nested(v_, path + "/result", result)
        ContractCheck.nested(v_, path + "/tag", tag)
        ContractCheck.long(v_, path + "/retry_after", retryAfter, minimum = 1L)
        val present_ = mutableSetOf<String>()
        present_.add("tag_id")
        present_.add("result")
        if (tag != null) present_.add("tag")
        if (retryAfter != null) present_.add("retry_after")
        val c0_ = result.value in listOf("ok")
        ContractCheck.obj(v_, path, present_, conditionals = listOf(ContractCheck.Conditional(c0_, listOf("tag"), listOf(), listOf(), listOf("tag"))))
        return v_
    }
}

/**
 * The app is too old for this hub: its protocol_version is missing or below min_protocol_version
 * (reason 'protocol'), or its app_version is below min_app_version[platform] (reason
 * 'app_version'). Answer to auth or pair; the hub closes the connection with 4426 right after. The
 * app must not reconnect in a loop and must not reset its pairing: it shows a localized 'Please
 * update the app' hint built from reason, and retries only after an app update or a manual retry.
 * message is an English fallback for logs.
 * Schema: `schemas/ws/server/upgrade_required.json`.
 */
@Serializable
data class ServerUpgradeRequired(
    @EncodeDefault @SerialName("type") val type: String = TYPE,
    @SerialName("reason") val reason: UpgradeReason,
    @SerialName("message") val message: String,
    @SerialName("protocol_version") val protocolVersion: StrictLong,
    @SerialName("min_protocol_version") val minProtocolVersion: StrictLong,
    @SerialName("min_app_version") val minAppVersion: MinAppVersion,
    /**
     * Platform the app reported, null if missing or unknown.
     */
    @SerialName("platform") val platform: Platform? = null,
) : ContractValue, ServerMessage {
    companion object {
        const val TYPE: String = "upgrade_required"
    }

    override fun validate(path: String): List<ContractViolation> {
        val v_ = mutableListOf<ContractViolation>()
        ContractCheck.string(v_, path + "/type", type, const = TYPE)
        ContractCheck.nested(v_, path + "/reason", reason)
        ContractCheck.long(v_, path + "/protocol_version", protocolVersion, minimum = 1L)
        ContractCheck.long(v_, path + "/min_protocol_version", minProtocolVersion, minimum = 1L)
        ContractCheck.nested(v_, path + "/min_app_version", minAppVersion)
        ContractCheck.nested(v_, path + "/platform", platform)
        return v_
    }
}

/**
 * Exactly with status ready (tools/validate.py). HPKE base mode (RFC 9180, DHKEM(X25519,
 * HKDF-SHA256), HKDF-SHA256, ChaCha20Poly1305) to the public key the watch paired with
 * (onboard_start of its phone); info = "hub/watch-access/v1", aad = client_id as ASCII. Plaintext:
 * crypto/watch-access-plaintext.json. Known-answer vector: fixtures/crypto/onboard-seal-vectors
 * case watch-access-v1.
 */
@Serializable
data class ServerWatchAccessSealed(
    @SerialName("suite") val suite: String,
    /**
     * HPKE encapsulated key (32 bytes), base64url without padding.
     */
    @SerialName("enc") val enc: String,
    /**
     * AEAD ciphertext incl. 16-byte tag, base64url without padding.
     */
    @SerialName("ciphertext") val ciphertext: String,
) : ContractValue {
    override fun validate(path: String): List<ContractViolation> {
        val v_ = mutableListOf<ContractViolation>()
        ContractCheck.string(v_, path + "/suite", suite, const = "X25519-SHA256-ChaCha20Poly1305")
        ContractCheck.string(v_, path + "/enc", enc, rule = ContractCheck.StringRule(pattern = ContractPatterns.P36))
        ContractCheck.string(v_, path + "/ciphertext", ciphertext, rule = ContractCheck.StringRule(pattern = ContractPatterns.P78, maxLength = 262144))
        return v_
    }
}

/**
 * The Home Assistant access of a watch, sealed to the watch's key. Answer to watch_access_get, and
 * pushed unasked to every connection of the device that set the watch up when the watch's access
 * changes (new or rotated HA token, profile, rules, remote access, access hours). The phone passes
 * sealed on unchanged; it cannot open it. status: ready = sealed carries the watch's
 * client_config; pending = the watch holds a key that is not usable yet: not issued, or held back
 * until the integration has the watch's rules, or being replaced (client_config.token_error); a
 * push follows; gone = there is no watch of this device with this id (deleted, locked, or set up
 * by another device): the watch forgets its access.
 * Schema: `schemas/ws/server/watch_access.json`.
 */
@Serializable
data class ServerWatchAccess(
    @EncodeDefault @SerialName("type") val type: String = TYPE,
    @SerialName("client_id") val clientId: String,
    @SerialName("status") val status: ServerWatchAccessStatus,
    /**
     * Exactly with status ready (tools/validate.py). HPKE base mode (RFC 9180, DHKEM(X25519,
     * HKDF-SHA256), HKDF-SHA256, ChaCha20Poly1305) to the public key the watch paired with
     * (onboard_start of its phone); info = "hub/watch-access/v1", aad = client_id as ASCII. Plaintext:
     * crypto/watch-access-plaintext.json. Known-answer vector: fixtures/crypto/onboard-seal-vectors
     * case watch-access-v1.
     */
    @SerialName("sealed") val sealed: ServerWatchAccessSealed? = null,
    /**
     * Only with status gone for a child's watch the hub removed with a write: why (the phone tells its
     * user). The hub keeps it for that phone, so a phone that was offline gets it with the gone it
     * fetches later (watch_access_get). Missing = no reason given.
     */
    @SerialName("reason") val reason: WatchRemovedReason? = null,
) : ContractValue, ServerMessage {
    companion object {
        const val TYPE: String = "watch_access"
    }

    /** Without the values of sensitive fields (x-sensitive). */
    override fun toString(): String = "ServerWatchAccess(" + listOf("type=" + type, "clientId=" + clientId, "status=" + status, "sealed=<redacted>", "reason=" + reason).joinToString(", ") + ")"

    override fun validate(path: String): List<ContractViolation> {
        val v_ = mutableListOf<ContractViolation>()
        ContractCheck.string(v_, path + "/type", type, const = TYPE)
        ContractCheck.string(v_, path + "/client_id", clientId, rule = ContractCheck.StringRule(pattern = ContractPatterns.P1))
        ContractCheck.nested(v_, path + "/status", status)
        ContractCheck.nested(v_, path + "/sealed", sealed)
        ContractCheck.nested(v_, path + "/reason", reason)
        return v_
    }
}

/**
 * Writable tile settings of an area entity placement. Every field is optional; null or absent =
 * app default. Allowed values per domain: data/tile-capabilities.json (the hub answers 422 for
 * anything else). Clients MUST fall back to the default for unknown enum values and for values not
 * allowed for the domain. The hub always delivers the settings; an app may show the standard card
 * instead (guests always do).
 */
@Serializable
data class TileSettingsBase(
    /**
     * null = Home Assistant icon (attributes.icon), else the app's domain/state symbol. A custom icon
     * is static (replaces the state-dependent symbol).
     */
    @SerialName("icon") val icon: String? = null,
    @SerialName("variant") val variant: TileVariant? = null,
    @SerialName("secondary") val secondary: TileSecondary? = null,
    @SerialName("tap_action") val tapAction: TileTapAction? = null,
    @SerialName("hold_action") val holdAction: TileHoldAction? = null,
    /**
     * Ask before toggle/run. Locks and alarm panels always confirm (field not allowed there).
     */
    @SerialName("confirm") val confirm: StrictBoolean? = null,
    /**
     * Palette color family, applied only while the entity is active. null = domain tint.
     */
    @SerialName("accent") val accent: TileAccent? = null,
    /**
     * Form factors that do not show this card (1-2 entries; all three = use is_visible). Filtered by
     * the app, not a security boundary.
     */
    @SerialName("hidden_on") val hiddenOn: List<TileFormFactor>? = null,
) : ContractValue {
    override fun validate(path: String): List<ContractViolation> {
        val v_ = mutableListOf<ContractViolation>()
        ContractCheck.string(v_, path + "/icon", icon, rule = ContractCheck.StringRule(pattern = ContractPatterns.P10, maxLength = 100))
        ContractCheck.nested(v_, path + "/variant", variant)
        ContractCheck.nested(v_, path + "/secondary", secondary)
        ContractCheck.nested(v_, path + "/tap_action", tapAction)
        ContractCheck.nested(v_, path + "/hold_action", holdAction)
        ContractCheck.nested(v_, path + "/accent", accent)
        ContractCheck.items(v_, path + "/hidden_on", hiddenOn, minItems = 1, maxItems = 2, unique = true)
        ContractCheck.nested(v_, path + "/hidden_on", hiddenOn)
        return v_
    }
}
